//! ID types and timestamp for the harness protocol.
//!
//! This module provides a [`newtype_id!`] macro for generating strongly-typed
//! UUID wrappers, as well as a [`Timestamp`] wrapper around `chrono::DateTime<Utc>`.

use std::fmt::{self, Display, Formatter};
use std::ops::Deref;
use std::str::FromStr;

use chrono::{DateTime, Utc};
use serde::{Deserialize, Serialize};
use uuid::Uuid;

/// Macro to create a newtype ID wrapping a [`Uuid`].
///
/// The generated struct implements [`Display`], [`FromStr`], [`Serialize`],
/// and [`Deserialize`] for seamless serialization.
macro_rules! newtype_id {
    ($(#[$meta:meta])* $name:ident) => {
        $(#[$meta])*
        #[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
        #[repr(transparent)]
        pub struct $name(Uuid);

        impl $name {
            /// Creates a new ID with a random UUIDv4.
            pub fn new() -> Self {
                Self(Uuid::new_v4())
            }

            /// Wraps an existing [`Uuid`] into this ID type.
            pub fn from_uuid(u: Uuid) -> Self {
                Self(u)
            }

            /// Returns a reference to the inner [`Uuid`].
            pub fn as_uuid(&self) -> &Uuid {
                &self.0
            }
        }

        impl Display for $name {
            fn fmt(&self, f: &mut Formatter<'_>) -> fmt::Result {
                write!(f, "{}", self.0)
            }
        }

        impl FromStr for $name {
            type Err = uuid::Error;

            fn from_str(s: &str) -> Result<Self, Self::Err> {
                Uuid::from_str(s).map(Self)
            }
        }
    };
}

