    /// Verifies that `new()` produces a valid UUID and that `Display`/`FromStr` round-trips.
    #[test]
    fn session_id_roundtrip() {
        let id = SessionId::new();
        let s = id.to_string();
        let parsed: SessionId = s.parse().expect("valid UUID string");
        assert_eq!(id, parsed);
