    /// Verifies that `Timestamp::now()` produces a time close to the system clock.
    #[test]
    fn timestamp_now_is_recent() {
        let before = Utc::now();
        let ts = Timestamp::now();
        let after = Utc::now();
        let t = ts.as_datetime();
        assert!(
            *t >= before || *t <= after,
            "timestamp should be between before and after"
        );
    }

    /// Verifies that two consecutively generated IDs are distinct.
    #[test]
    fn ids_are_unique() {
        let a = SessionId::new();
        let b = SessionId::new();
