//! Message types for the harness protocol.
//!
//! This module provides the core message abstractions used to communicate
//! between agents, tools, and model backends.

use serde::{Deserialize, Serialize};

use crate::ids::{MessageId, Timestamp, ToolCallId};

// ---------------------------------------------------------------------------
// Placeholder types (forward references to `crate::tools`, task 4)
// ---------------------------------------------------------------------------

/// Placeholder for `ToolCall` — will be defined in `crate::tools` (task 4).
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct ToolCall {
    /// Unique identifier for this tool invocation.
    pub id: ToolCallId,
    /// The name of the tool being called.
    pub name: String,
    /// Arguments to pass to the tool.
    pub arguments: serde_json::Value,
}

/// Placeholder for `ToolResultSummary` — will be defined in `crate::tools` (task 4).
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct ToolResultSummary {
    /// Whether the tool execution resulted in an error.
    pub is_error: bool,
    /// The output or error message from the tool.
    pub output: serde_json::Value,
}

// ---------------------------------------------------------------------------
// MessageRole
// ---------------------------------------------------------------------------

/// The role of a message participant.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
pub enum MessageRole {
    /// System-level instruction or prompt.
    System,
    /// End-user input.
    User,
    /// Agent / model response.
    Assistant,
    /// Tool invocation result.
    Tool,
}

// ---------------------------------------------------------------------------
// ContentBlock
// ---------------------------------------------------------------------------

/// A single block of content within a message.
///
/// Messages can contain heterogeneous blocks — text, tool invocations,
/// tool results, and (in a future iteration) image attachments.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub enum ContentBlock {
    /// Plain text content.
    Text {
        text: String,
    },
    /// A request to invoke a tool.
    ToolUse {
        call: ToolCall,
    },
    /// The result of a previously issued tool call.
    ToolResult {
        call_id: ToolCallId,
        result: ToolResultSummary,
    },
    /// Placeholder — image content; shape to be defined in a future task.
    Image {
        /// Placeholder — will hold image data or URL.
        placeholder: serde_json::Value,
    },
}

// ---------------------------------------------------------------------------
// AgentMessage
// ---------------------------------------------------------------------------

/// A complete message exchanged as part of an agent conversation.
#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
pub struct AgentMessage {
    /// Unique message identifier.
    pub id: MessageId,
    /// The participant role that produced this message.
    pub role: MessageRole,
    /// The content blocks that make up this message.
    pub content: Vec<ContentBlock>,
    /// Timestamp of when this message was created.
    pub created_at: Timestamp,
}

// ---------------------------------------------------------------------------
// Tests
// ---------------------------------------------------------------------------

#[cfg(test)]
mod tests {
    use super::*;
    use crate::ids::Timestamp;

    /// Round-trip JSON serialization of a message containing only text blocks.
    #[test]
    fn text_message_roundtrip() {
        let msg = AgentMessage {
            id: MessageId::new(),
            role: MessageRole::User,
            content: vec![ContentBlock::Text {
                text: "Hello, world!".to_string(),
            }],
            created_at: Timestamp::now(),
        };

        let json = serde_json::to_string(&msg).expect("serialize text message");
        let deserialized: AgentMessage =
            serde_json::from_str(&json).expect("deserialize text message");

        assert_eq!(msg.id, deserialized.id);
        assert_eq!(msg.role, deserialized.role);
        assert_eq!(msg.created_at, deserialized.created_at);
        assert_eq!(msg.content, deserialized.content);
    }

    /// Round-trip JSON serialization of a message containing a tool-use block.
    #[test]
    fn tool_use_message_roundtrip() {
        let msg = AgentMessage {
            id: MessageId::new(),
            role: MessageRole::Assistant,
            content: vec![
                ContentBlock::Text {
                    text: "Let me look that up.".to_string(),
                },
                ContentBlock::ToolUse {
                    call: ToolCall {
                        id: ToolCallId::new(),
                        name: "search".to_string(),
                        arguments: serde_json::json!({"query": "rust programming"}),
                    },
                },
            ],
            created_at: Timestamp::now(),
        };

        let json = serde_json::to_string(&msg).expect("serialize tool-use message");
        let deserialized: AgentMessage =
            serde_json::from_str(&json).expect("deserialize tool-use message");

        assert_eq!(msg.id, deserialized.id);
        assert_eq!(msg.role, deserialized.role);
        assert_eq!(msg.created_at, deserialized.created_at);
        assert_eq!(msg.content, deserialized.content);
    }

    /// Round-trip JSON serialization of a message containing a tool-result block.
    #[test]
    fn tool_result_message_roundtrip() {
        let call_id = ToolCallId::new();
        let msg = AgentMessage {
            id: MessageId::new(),
            role: MessageRole::Tool,
            content: vec![ContentBlock::ToolResult {
                call_id,
                result: ToolResultSummary {
                    is_error: false,
                    output: serde_json::json!({"results": ["rust is a systems language"]}),
                },
            }],
            created_at: Timestamp::now(),
        };

        let json = serde_json::to_string(&msg).expect("serialize tool-result message");
        let deserialized: AgentMessage =
            serde_json::from_str(&json).expect("deserialize tool-result message");

        assert_eq!(msg.id, deserialized.id);
        assert_eq!(msg.role, deserialized.role);
        assert_eq!(msg.created_at, deserialized.created_at);
        assert_eq!(msg.content, deserialized.content);
    }
}

