//! Tool descriptor, capability, call, and result types for the harness protocol.
//!
//! This module defines the core tool abstractions: how tools are described,
//! how their usage is policed, how they are called, and how results are reported.

use std::collections::HashMap;

use serde::{Deserialize, Serialize};

use crate::ids::{ToolCallId, ToolId};

// ---------------------------------------------------------------------------
// Tool descriptor & policy
// ---------------------------------------------------------------------------

/// Describes a tool's identity, purpose, and expected input schema.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ToolDescriptor {
    /// Unique identifier for this tool.
    pub id: ToolId,
    /// Human-readable name of the tool.
    pub name: String,
    /// Description of what the tool does.
    pub description: String,
    /// JSON Schema describing the expected input arguments.
    pub input_schema: serde_json::Value,
}

/// Determines how a tool's invocation is authorised.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub enum PermissionMode {
    /// Automatically allowed.
    Allow,
    /// Requires user confirmation.
    Ask,
    /// Blocked.
    Deny,
}

/// Access policy for a single tool.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ToolPolicy {
    /// The permission level assigned to this tool.
    pub permission: PermissionMode,
    /// Whether the tool is currently enabled.
    pub enabled: bool,
}

/// A tool's full capability record, combining its descriptor with a policy.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ToolCapability {
    /// The tool's descriptor.
    pub descriptor: ToolDescriptor,
    /// The access policy for this tool.
    pub policy: ToolPolicy,
    /// Whether this tool can be delegated to sub-agents.
    pub delegatable: bool,
}

// ---------------------------------------------------------------------------
// Agent toolset
// ---------------------------------------------------------------------------

/// The collection of tools an agent has access to.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct AgentToolset {
    /// Map of tool ID to its capability record.
    pub tools: HashMap<ToolId, ToolCapability>,
}

impl AgentToolset {
    /// Returns descriptors for all currently enabled tools.
    ///
    /// This filters the internal map to only those [`ToolCapability`] entries
    /// whose [`ToolPolicy::enabled`] field is `true`.
    pub fn enabled_descriptors(&self) -> Vec<&ToolDescriptor> {
        self.tools
            .values()
            .filter(|tc| tc.policy.enabled)
            .map(|tc| &tc.descriptor)
            .collect()
    }
}

// ---------------------------------------------------------------------------
// Tool call & result types
// ---------------------------------------------------------------------------

/// Represents an invocation of a tool.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ToolCall {
    /// Unique identifier for this call.
    pub id: ToolCallId,
    /// The name of the tool being called.
    pub name: String,
    /// The arguments passed to the tool, as a JSON value.
    pub arguments: serde_json::Value,
}

/// The outcome of a tool call.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ToolResult {
    /// The ID of the call this result belongs to.
    pub call_id: ToolCallId,
    /// The output produced by the tool.
    pub output: serde_json::Value,
    /// Whether the tool execution resulted in an error.
    pub is_error: bool,
}

/// A lightweight summary of a tool result, suitable for logging or preview.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ToolResultSummary {
    /// Whether the tool execution resulted in an error.
    pub has_error: bool,
    /// A short textual preview of the output.
    pub output_preview: String,
}

/// Categorised errors that can occur during tool execution.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub enum ToolError {
    /// The tool reported a failure during execution.
    ExecutionFailed,
    /// The call was not authorised.
    PermissionDenied,
    /// The tool did not respond within the allowed time.
    Timeout,
    /// An internal system error occurred.
    Internal,
}

/// Progress update for a long-running tool invocation.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ToolProgress {
    /// A human-readable status message.
    pub status: String,
    /// Progress fraction between 0.0 and 1.0.
    pub fraction: f64,
}

// ---------------------------------------------------------------------------
// Tests
// ---------------------------------------------------------------------------

#[cfg(test)]
mod tests {
    use super::*;
    use crate::ids::ToolId;

    /// Verifies that `enabled_descriptors` returns only tools whose policy has
    /// `enabled: true`, skipping disabled ones.
    #[test]
    fn enabled_descriptors_filters_disabled_tools() {
        let id_a = ToolId::new();
        let id_b = ToolId::new();
        let id_c = ToolId::new();

        let mut tools = HashMap::new();

        // Enabled tool
        tools.insert(
            id_a,
            ToolCapability {
                descriptor: ToolDescriptor {
                    id: id_a,
                    name: "alpha".into(),
                    description: "First tool".into(),
                    input_schema: serde_json::json!({}),
                },
                policy: ToolPolicy {
                    permission: PermissionMode::Allow,
                    enabled: true,
                },
                delegatable: false,
            },
        );

        // Disabled tool
        tools.insert(
            id_b,
            ToolCapability {
                descriptor: ToolDescriptor {
                    id: id_b,
                    name: "beta".into(),
                    description: "Second tool".into(),
                    input_schema: serde_json::json!({}),
                },
                policy: ToolPolicy {
                    permission: PermissionMode::Deny,
                    enabled: false,
                },
                delegatable: false,
            },
        );

        // Another enabled tool
        tools.insert(
            id_c,
            ToolCapability {
                descriptor: ToolDescriptor {
                    id: id_c,
                    name: "gamma".into(),
                    description: "Third tool".into(),
                    input_schema: serde_json::json!({"type": "object"}),
                },
                policy: ToolPolicy {
                    permission: PermissionMode::Ask,
                    enabled: true,
                },
                delegatable: true,
            },
        );

        let set = AgentToolset { tools };
        let enabled = set.enabled_descriptors();

        assert_eq!(enabled.len(), 2, "expected exactly 2 enabled tools");
        assert!(
            enabled.iter().any(|d| d.name == "alpha"),
            "missing enabled tool alpha"
        );
        assert!(
            enabled.iter().any(|d| d.name == "gamma"),
            "missing enabled tool gamma"
        );
        assert!(
            enabled.iter().all(|d| d.name != "beta"),
            "disabled tool beta should not appear"
        );
    }

    /// Verifies that `enabled_descriptors` returns an empty vec when no tools
    /// are enabled.
    #[test]
    fn enabled_descriptors_empty_when_none_enabled() {
        let id = ToolId::new();
        let mut tools = HashMap::new();
        tools.insert(
            id,
            ToolCapability {
                descriptor: ToolDescriptor {
                    id,
                    name: "only_tool".into(),
                    description: "Only tool".into(),
                    input_schema: serde_json::json!({"type": "object"}),
                },
                policy: ToolPolicy {
                    permission: PermissionMode::Deny,
                    enabled: false,
                },
                delegatable: false,
            },
        );

        let set = AgentToolset { tools };
        let enabled = set.enabled_descriptors();
        assert!(enabled.is_empty(), "expected no enabled tools");
    }
}

