//! Usage tracking primitives for the harness protocol.
//!
//! This module provides [`UsageValue`], a wrapper around `Option<u64>` that
//! enforces the invariant that **unknown is not zero**.  When aggregating,
//! if any operand is unknown (`None`) the result remains unknown — we never
//! silently treat missing data as a zero count.
//!
//! Higher-level types built on this include [`ModelUsage`], [`Cost`],
//! [`UsageRecord`], [`AgentBudget`], and several placeholder aggregate
//! structures used for session- and agent-level reporting.

use rust_decimal::Decimal;
use serde::{Deserialize, Serialize};

// ---------------------------------------------------------------------------
// UsageValue — the core unknown-safe counter
// ---------------------------------------------------------------------------

/// A counter that is either a known `u64` value or unknown (`None`).
///
/// The key invariant: **unknown is not zero**.  If a value was not reported
/// (e.g. the provider did not return a token count) we represent that as
/// `None` rather than `0`, so that aggregations do not accidentally
/// introduce false precision.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
pub struct UsageValue(Option<u64>);

impl UsageValue {
    /// Wraps an optional `u64` into a `UsageValue`.
    ///
    /// `None` means the value is unknown; `Some(0)` is a known zero.
    pub fn new(v: Option<u64>) -> Self {
        Self(v)
    }

    /// Returns `true` if the value is unknown (was never reported).
    pub fn is_unknown(&self) -> bool {
        self.0.is_none()
    }

    /// Returns `true` if the value is a known zero.
    ///
    /// Note that unknown values (`None`) are *not* considered zero.
    pub fn is_zero(&self) -> bool {
        self.0 == Some(0)
    }

    /// Returns the inner `Option<u64>`.
    pub fn value(&self) -> Option<u64> {
        self.0
    }

    /// Adds two `UsageValue`s, preserving the unknown-invariant.
    ///
    /// - If **both** values are known (`Some`), returns `Some(a + b)`.
    /// - If **either** value is unknown (`None`), returns `None` — the
    ///   result stays unknown.
    pub fn checked_add(self, other: Self) -> Self {
        match (self.0, other.0) {
            (Some(a), Some(b)) => Self(Some(a + b)),
            _ => Self(None),
        }
    }
}

// ---------------------------------------------------------------------------
// ModelUsage
// ---------------------------------------------------------------------------

/// Token usage broken down by category, as reported by a model provider.
///
/// Every field uses [`UsageValue`] so that missing provider data is never
/// silently treated as zero.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ModelUsage {
    pub input_tokens: UsageValue,
    pub output_tokens: UsageValue,
    pub cache_read_tokens: UsageValue,
    pub cache_write_tokens: UsageValue,
    pub reasoning_tokens: UsageValue,
    pub total_tokens: UsageValue,
}

// ---------------------------------------------------------------------------
// CostSource & Cost
// ---------------------------------------------------------------------------

/// Identifies how a cost figure was determined.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub enum CostSource {
    /// The provider returned an exact cost in its response.
    ProviderReported,
    /// The cost was calculated from token counts and a known pricing table.
    Calculated,
    /// The cost is an estimate (e.g. extrapolated mid-run).
    Estimated,
}

/// A monetary cost associated with a usage record or request.
///
/// Both fields are optional: `amount_usd` may be `None` when cost has not
/// yet been determined, and `source` may be `None` to indicate that no
/// costing method has been applied.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct Cost {
    pub amount_usd: Option<Decimal>,
    pub source: Option<CostSource>,
}

// ---------------------------------------------------------------------------
// UsageRecord
// ---------------------------------------------------------------------------

/// A complete record of usage for a single request or operation.
///
/// Ties together the model-level token counts, the computed or reported
/// cost, and an optional breakdown of tool-call token usage.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct UsageRecord {
    /// Per-category token usage from the model provider.
    pub model_usage: ModelUsage,
    /// Monetary cost associated with this record.
    pub cost: Cost,
    /// Token usage attributed to tool calls, if tracked separately.
    pub tool_usage: Option<ModelUsage>,
}

// ---------------------------------------------------------------------------
// AgentBudget
// ---------------------------------------------------------------------------

/// Budgetary limits for an agent run or session.
///
/// All fields are optional so that a budget can express "no limit" for any
/// dimension.  A `None` means unlimited / unbounded.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct AgentBudget {
    pub max_input_tokens: Option<u64>,
    pub max_output_tokens: Option<u64>,
    pub max_total_tokens: Option<u64>,
    pub max_cost_usd: Option<Decimal>,
    pub max_requests: Option<u64>,
    pub max_tool_calls: Option<u64>,
    pub max_children: Option<u32>,
    pub max_depth: Option<u32>,
}

// ---------------------------------------------------------------------------
// Placeholder aggregate types
// ---------------------------------------------------------------------------

/// Cumulative usage across multiple requests within a session.
#[derive(Debug, Clone, Default, Serialize, Deserialize)]
pub struct CumulativeUsage {
    pub total_tokens: UsageValue,
    pub total_cost: Option<Decimal>,
    pub total_requests: u64,
}

/// Usage attributed to a specific context window.
#[derive(Debug, Clone, Default, Serialize, Deserialize)]
pub struct ContextUsage {
    pub tokens_loaded: UsageValue,
    pub tokens_evicted: UsageValue,
}

/// Usage for a single run (agent invocation).
#[derive(Debug, Clone, Default, Serialize, Deserialize)]
pub struct RunUsage {
    pub model_usage: Option<ModelUsage>,
    pub cost: Option<Cost>,
    pub request_count: u64,
    pub tool_call_count: u64,
}

/// High-level usage metrics for an agent.
#[derive(Debug, Clone, Default, Serialize, Deserialize)]
pub struct AgentUsageMetrics {
    pub total_runs: u64,
    pub total_requests: u64,
    pub total_tool_calls: u64,
    pub total_tokens: UsageValue,
    pub total_cost: Option<Decimal>,
}

/// Summary of an agent's usage over a time window.
#[derive(Debug, Clone, Default, Serialize, Deserialize)]
pub struct AgentUsageSummary {
    pub metrics: AgentUsageMetrics,
    pub window_start: Option<String>,
    pub window_end: Option<String>,
}

/// A point-in-time snapshot of an agent's usage.
#[derive(Debug, Clone, Default, Serialize, Deserialize)]
pub struct AgentUsageSnapshot {
    pub agent_id: String,
    pub metrics: AgentUsageMetrics,
    pub timestamp: String,
}

/// A point-in-time snapshot of a session's usage.
#[derive(Debug, Clone, Default, Serialize, Deserialize)]
pub struct SessionUsageSnapshot {
    pub session_id: String,
    pub cumulative: CumulativeUsage,
    pub timestamp: String,
}

// ---------------------------------------------------------------------------
// Tests
// ---------------------------------------------------------------------------

#[cfg(test)]
mod tests {
    use super::*;

    // -----------------------------------------------------------------------
    // UsageValue construction and queries
    // -----------------------------------------------------------------------

    #[test]
    fn unknown_value() {
        let v = UsageValue::new(None);
        assert!(v.is_unknown());
        assert!(!v.is_zero());
        assert_eq!(v.value(), None);
    }

    #[test]
    fn known_zero() {
        let v = UsageValue::new(Some(0));
        assert!(!v.is_unknown());
        assert!(v.is_zero());
        assert_eq!(v.value(), Some(0));
    }

    #[test]
    fn known_non_zero() {
        let v = UsageValue::new(Some(42));
        assert!(!v.is_unknown());
        assert!(!v.is_zero());
        assert_eq!(v.value(), Some(42));
    }

    // -----------------------------------------------------------------------
    // checked_add — the unknown invariant
    // -----------------------------------------------------------------------

    #[test]
    fn add_two_known_values() {
        let a = UsageValue::new(Some(10));
        let b = UsageValue::new(Some(20));
        let sum = a.checked_add(b);
        assert!(!sum.is_unknown());
        assert_eq!(sum.value(), Some(30));
    }

    #[test]
    fn add_known_and_unknown_yields_unknown() {
        let a = UsageValue::new(Some(10));
        let b = UsageValue::new(None);
        let sum = a.checked_add(b);
        // The unknown value poisons the result
        assert!(sum.is_unknown());
        assert_eq!(sum.value(), None);
    }

    #[test]
    fn add_unknown_and_known_yields_unknown() {
        let a = UsageValue::new(None);
        let b = UsageValue::new(Some(5));
        let sum = a.checked_add(b);
        assert!(sum.is_unknown());
        assert_eq!(sum.value(), None);
    }

    #[test]
    fn add_two_unknowns_yields_unknown() {
        let a = UsageValue::new(None);
        let b = UsageValue::new(None);
        let sum = a.checked_add(b);
        assert!(sum.is_unknown());
        assert_eq!(sum.value(), None);
    }

    // -----------------------------------------------------------------------
    // Aggregation: unknown values survive composition
    // -----------------------------------------------------------------------

    #[test]
    fn aggregation_preserves_unknown() {
        // Simulate a scenario where the provider did not report
        // cache_write_tokens. After aggregating two model usages,
        // cache_write_tokens must remain unknown.
        let usage1 = ModelUsage {
            input_tokens: UsageValue::new(Some(100)),
            output_tokens: UsageValue::new(Some(50)),
            cache_read_tokens: UsageValue::new(Some(10)),
            cache_write_tokens: UsageValue::new(None), // not reported
            reasoning_tokens: UsageValue::new(Some(5)),
            total_tokens: UsageValue::new(Some(165)),
        };

        let usage2 = ModelUsage {
            input_tokens: UsageValue::new(Some(200)),
            output_tokens: UsageValue::new(Some(75)),
            cache_read_tokens: UsageValue::new(Some(20)),
            cache_write_tokens: UsageValue::new(None), // still not reported
            reasoning_tokens: UsageValue::new(Some(10)),
            total_tokens: UsageValue::new(Some(305)),
        };

        // Aggregate field-by-field
        let aggregated = ModelUsage {
            input_tokens: usage1.input_tokens.checked_add(usage2.input_tokens),
            output_tokens: usage1.output_tokens.checked_add(usage2.output_tokens),
            cache_read_tokens: usage1.cache_read_tokens.checked_add(usage2.cache_read_tokens),
            cache_write_tokens: usage1
                .cache_write_tokens
                .checked_add(usage2.cache_write_tokens),
            reasoning_tokens: usage1.reasoning_tokens.checked_add(usage2.reasoning_tokens),
            total_tokens: usage1.total_tokens.checked_add(usage2.total_tokens),
        };

        // Known fields should sum correctly
        assert_eq!(aggregated.input_tokens.value(), Some(300));
        assert_eq!(aggregated.output_tokens.value(), Some(125));
        assert_eq!(aggregated.cache_read_tokens.value(), Some(30));
        assert_eq!(aggregated.reasoning_tokens.value(), Some(15));
        assert_eq!(aggregated.total_tokens.value(), Some(470));

        // cache_write_tokens was unknown in both inputs, so it stays unknown
        assert!(aggregated.cache_write_tokens.is_unknown());
    }

    #[test]
    fn partially_known_aggregation() {
        // One record has cache_write_tokens, the other does not.
        // The aggregate must become unknown for that field.
        let a = ModelUsage {
            input_tokens: UsageValue::new(Some(10)),
            output_tokens: UsageValue::new(Some(5)),
            cache_read_tokens: UsageValue::new(None),
            cache_write_tokens: UsageValue::new(Some(2)),
            reasoning_tokens: UsageValue::new(Some(1)),
            total_tokens: UsageValue::new(Some(18)),
        };

        let b = ModelUsage {
            input_tokens: UsageValue::new(Some(20)),
            output_tokens: UsageValue::new(Some(10)),
            cache_read_tokens: UsageValue::new(Some(3)),
            cache_write_tokens: UsageValue::new(None), // not reported this time
            reasoning_tokens: UsageValue::new(Some(2)),
            total_tokens: UsageValue::new(Some(35)),
        };

        let agg = ModelUsage {
            input_tokens: a.input_tokens.checked_add(b.input_tokens),
            output_tokens: a.output_tokens.checked_add(b.output_tokens),
            cache_read_tokens: a.cache_read_tokens.checked_add(b.cache_read_tokens),
            cache_write_tokens: a.cache_write_tokens.checked_add(b.cache_write_tokens),
            reasoning_tokens: a.reasoning_tokens.checked_add(b.reasoning_tokens),
            total_tokens: a.total_tokens.checked_add(b.total_tokens),
        };

        assert_eq!(agg.input_tokens.value(), Some(30));
        assert_eq!(agg.output_tokens.value(), Some(15));
        // cache_read_tokens: known + unknown => unknown
        assert!(agg.cache_read_tokens.is_unknown());
        // cache_write_tokens: known + unknown => unknown
        assert!(agg.cache_write_tokens.is_unknown());
        assert_eq!(agg.reasoning_tokens.value(), Some(3));
        assert_eq!(agg.total_tokens.value(), Some(53));
    }

    // -----------------------------------------------------------------------
    // Default placeholder structs
    // -----------------------------------------------------------------------

    #[test]
    fn placeholder_defaults() {
        // These should all construct without panicking.
        let _ = CumulativeUsage::default();
        let _ = ContextUsage::default();
        let _ = RunUsage::default();
        let _ = AgentUsageMetrics::default();
        let _ = AgentUsageSummary::default();
        let _ = AgentUsageSnapshot::default();
        let _ = SessionUsageSnapshot::default();
    }
}

