//! Effect types for the harness protocol.
//!
//! This module defines [`AgentEffect`] — the set of side-effects that an
//! agent's transition function may request — together with the supporting
//! types that parameterise those effects: tool requests, permission requests,
//! session mutations, spawn specifications, and policy enums.

use serde::{Deserialize, Serialize};

use crate::backend::{BackendReference, ExecutionRequest};
use crate::ids::{AgentId, PermissionId, ToolId};
use crate::tools::{AgentToolset, PermissionMode, ToolCall};
use crate::usage::AgentBudget;
use crate::commands::AgentResult;

// ---------------------------------------------------------------------------
// ToolRequest, PermissionRequest, SessionMutation
// ---------------------------------------------------------------------------

/// A request to execute a specific tool.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ToolRequest {
    /// The tool call to execute.
    pub call: ToolCall,
    /// The permission mode governing this tool's execution.
    pub permission: PermissionMode,
}

/// A request for the user to grant or deny permission for a tool call.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct PermissionRequest {
    /// Unique identifier for this permission request.
    pub id: PermissionId,
    /// The tool call that requires permission.
    pub tool_call: ToolCall,
    /// The agent that initiated the tool call.
    pub agent_id: AgentId,
}

/// A mutation to be persisted to the session store.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct SessionMutation {
    /// A human-readable description of the mutation.
    pub description: String,
}

// ---------------------------------------------------------------------------
// BackendPolicy
// ---------------------------------------------------------------------------

/// Specifies how a child agent's backend is determined.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub enum BackendPolicy {
    /// Inherit the parent agent's backend.
    Inherit,
    /// Use an explicitly specified backend reference.
    Explicit(BackendReference),
}

// ---------------------------------------------------------------------------
// ToolInheritance
// ---------------------------------------------------------------------------

/// Specifies how a child agent inherits or overrides its parent's toolset.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub enum ToolInheritance {
    /// Child inherits all tools from the parent.
    InheritAll,
    /// Child inherits only the specified subset of the parent's tools.
    Subset(Vec<ToolId>),
    /// Child receives an entirely new toolset (replace parent's toolset).
    Replace(AgentToolset),
}

// ---------------------------------------------------------------------------
// WorkspacePolicy
// ---------------------------------------------------------------------------

/// Specifies how a child agent's workspace is configured.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub enum WorkspacePolicy {
    /// Inherit the parent's workspace.
    Inherit,
    /// Read-only access to the parent's workspace.
    ReadOnly,
    /// A snapshot (point-in-time copy) of the workspace.
    Snapshot,
    /// A new git worktree for the child.
    NewWorktree,
}

// ---------------------------------------------------------------------------
// SpawnMode
// ---------------------------------------------------------------------------

/// Execution mode for a spawned child agent.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub enum SpawnMode {
    /// The parent awaits the child's result before continuing.
    AwaitResult,
    /// The child runs concurrently with the parent.
    Concurrent,
}

// ---------------------------------------------------------------------------
// SpawnAgentSpec
// ---------------------------------------------------------------------------

/// Specification for spawning a child agent.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct SpawnAgentSpec {
    /// Optional role label for the child (e.g. "researcher", "coder").
    pub role: Option<String>,
    /// Backend policy — inherit parent or use explicit backend.
    pub backend: BackendPolicy,
    /// Tool inheritance strategy.
    pub tools: ToolInheritance,
    /// Workspace policy for the child.
    pub workspace: WorkspacePolicy,
    /// Budget constraints for the child.
    pub budget: AgentBudget,
    /// Execution mode (await result or concurrent).
    pub mode: SpawnMode,
}

// ---------------------------------------------------------------------------
// Placeholder for AgentEvent (forward reference)
// ---------------------------------------------------------------------------

/// Placeholder for `AgentEvent` — will be defined in `crate::events` (T1.7).
///
/// This is a minimal placeholder so that [`AgentEffect::Emit`] can exist
/// in this module before the full event type is introduced. Once `events.rs`
/// is created, this type should be removed and replaced with an import from
/// `crate::events::AgentEvent`.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub enum AgentEvent {
    /// Placeholder variant — will be replaced by the real event variants.
    Placeholder,
}

// ---------------------------------------------------------------------------
// AgentEffect
// ---------------------------------------------------------------------------

/// A side-effect requested by an agent's transition function.
///
/// The runtime interprets these effects and performs the corresponding
/// actions (executing a backend request, running a tool, spawning a child,
/// persisting state, emitting events, etc.). The agent core itself never
/// performs I/O — it only produces effects.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub enum AgentEffect {
    /// Execute a request against the configured execution backend.
    ExecuteBackend {
        /// The execution request to send.
        request: ExecutionRequest,
    },

    /// Execute a tool call.
    ExecuteTool {
        /// The tool request to execute.
        request: ToolRequest,
    },

    /// Spawn a child agent with the given specification.
    SpawnAgent {
        /// The specification for the child agent.
        spec: SpawnAgentSpec,
    },

    /// Request user permission before proceeding.
    RequestPermission {
        /// The permission request to present to the user.
        request: PermissionRequest,
    },

    /// Persist a mutation to the session store.
    Persist {
        /// The mutation to persist.
        mutation: SessionMutation,
    },

    /// Emit an observable event (for frontends, logging, or telemetry).
    Emit {
        /// The event to emit.
        event: AgentEvent,
    },

    /// Signal that the current run has completed with the given result.
    FinishRun {
        /// The final result of the run.
        result: AgentResult,
    },
}

