//! Agent state types for the harness core.
//!
//! This module defines [`PendingToolCall`] and [`AgentState`] — the durable
//! state that an agent carries across commands and transitions.  State is
//! mutated by [`Agent::apply`](crate::agent::Agent::apply) and observed by
//! frontends via snapshots and events.

use std::collections::HashMap;

use harness_protocol::commands::{AgentError, AgentOperation, AgentStatus};
use harness_protocol::ids::{AgentId, RunId, Timestamp, ToolCallId};
use harness_protocol::messages::AgentMessage;
use harness_protocol::tools::ToolCall;

// ---------------------------------------------------------------------------
// PendingToolCall
// ---------------------------------------------------------------------------

/// A tool call that has been requested by the model but has not yet completed.
///
/// The agent tracks pending tool calls so it can correlate results back to
/// the original request and enforce transcript invariants (every tool call
/// must have a matching result before the next conversational message).
#[derive(Debug, Clone)]
pub struct PendingToolCall {
    /// The tool call that is in-flight.
    pub call: ToolCall,
    /// When the tool call was started (or when the agent received the request).
    pub started_at: Timestamp,
}

// ---------------------------------------------------------------------------
// AgentState
// ---------------------------------------------------------------------------

/// The complete mutable state of an agent.
///
/// This is the single source of truth for where the agent is in its lifecycle,
/// what it is currently doing, what messages it has accumulated, and what
/// children or pending operations exist.
#[derive(Debug, Clone)]
pub struct AgentState {
    /// The high-level status of the agent (idle, streaming, executing, etc.).
    pub status: AgentStatus,

    /// Optional detail about what the agent is currently doing.
    /// Provides richer context than [`status`](AgentState::status) alone.
    pub current_operation: Option<AgentOperation>,

    /// The system prompt / instruction for the agent.
    pub system_prompt: String,

    /// The conversation transcript so far (messages in chronological order).
    pub messages: Vec<AgentMessage>,

    /// The identifier of the currently active run, if any.
    pub active_run: Option<RunId>,

    /// Tool calls that are currently in-flight, keyed by their unique call ID.
    pub pending_tools: HashMap<ToolCallId, PendingToolCall>,

    /// Identifiers of child agents that have been spawned and not yet completed.
    pub children: Vec<AgentId>,

    /// The last error encountered by the agent, if any.
    pub last_error: Option<AgentError>,
}

//! Agent domain entity for the harness core.
//!
//! This module defines [`Agent`] — the primary domain entity that owns state,
//! capabilities, usage, and budget.  An agent can be a root agent (no parent)
//! or a child/sub-agent spawned by another agent.
//!
//! # Lifecycle
//!
//! Agents are created via [`Agent::new`] and driven by commands via
//! [`Agent::apply`] (defined in `crate::transitions`).  They do **not**
//! perform I/O directly — instead they produce [`AgentEffect`]s that the
//! runtime interprets.

use harness_protocol::backend::{BackendBinding, BackendCapabilities};
use harness_protocol::commands::AgentStatus;
use harness_protocol::ids::{AgentId, SessionId};
use harness_protocol::tools::AgentToolset;
use harness_protocol::usage::AgentBudget;

use crate::agent_state::AgentState;

// ---------------------------------------------------------------------------
// WorkspaceCapabilities
// ---------------------------------------------------------------------------

/// Declares what workspace operations an agent is permitted to perform.
///
/// This is a sub-component of [`AgentCapabilities`] and will be expanded in
/// later phases (e.g. read-only / snapshot workspace policies for children).
#[derive(Debug, Clone)]
pub struct WorkspaceCapabilities {
    /// Whether the agent can read files from the workspace.
    pub can_read: bool,
    /// Whether the agent can write files to the workspace.
    pub can_write: bool,
    /// Whether the agent can search the workspace.
    pub can_search: bool,
}

// ---------------------------------------------------------------------------
// AgentCapabilities
// ---------------------------------------------------------------------------

/// The full set of capabilities granted to an agent.
///
/// This includes the tools the agent may use, whether it can spawn children,
/// its workspace permissions, and the capabilities advertised by its backend.
///
/// The sub-agent non-escalation invariant (spec §23) is enforced by
/// [`AgentCapabilities::derive_child_capabilities`], which will be added in a
/// follow-up task.
#[derive(Debug, Clone)]
pub struct AgentCapabilities {
    /// The tools this agent is allowed to use.
    pub tools: AgentToolset,
    /// Whether this agent may spawn sub-agents.
    pub can_spawn_agents: bool,
    /// Maximum allowed nesting depth for children (`None` = unlimited).
    pub max_child_depth: Option<u32>,
    /// Workspace access permissions.
    pub workspace: WorkspaceCapabilities,
    /// Capabilities of the backend this agent is bound to (cached for quick lookup).
    pub backend: BackendCapabilities,
}

// ---------------------------------------------------------------------------
// UsageLedger
// ---------------------------------------------------------------------------

/// A ledger of usage records for an agent.
///
/// This is a minimal placeholder that will be extended with aggregation
/// methods (self-usage, descendant-usage, tree-sum) in a follow-up task.
#[derive(Debug, Clone, Default)]
pub struct UsageLedger {
    /// The ordered list of usage records accumulated by this agent.
    pub records: Vec<harness_protocol::usage::UsageRecord>,
}

// ---------------------------------------------------------------------------
// Agent
// ---------------------------------------------------------------------------

/// An independent reasoning worker — the primary domain entity of the harness.
///
/// An agent owns:
/// - Identity (`id`, `session_id`, `parent_id`)
/// - State (`status`, transcript, pending tool calls, children, errors)
/// - Backend binding (which backend to use, how to reach it)
/// - Capabilities (what tools, operations, and permissions the agent has)
/// - Usage tracking (token counts, cost)
/// - Budget constraints (limits on tokens, cost, children)
///
/// Agents form a tree: a session has one root agent, and root agents may spawn
/// child agents.  Every agent (root or child) is a full `Agent` instance —
/// there is no separate `SubAgent` type.
#[derive(Debug, Clone)]
pub struct Agent {
    /// Unique identifier for this agent.
    pub id: AgentId,
    /// The session this agent belongs to.
    pub session_id: SessionId,
    /// The parent agent, if any (root agents have `None`).
    pub parent_id: Option<AgentId>,

    /// The agent's mutable state (status, transcript, pending tools, etc.).
    pub state: AgentState,

    /// The backend binding — a reference + descriptor identifying which
    /// execution backend this agent uses.
    pub backend: BackendBinding,

    /// The capabilities granted to this agent (tools, spawn permissions, etc.).
    pub capabilities: AgentCapabilities,

    /// The accumulated usage ledger for this agent (does **not** include
    /// descendant usage — that is aggregated separately).
    pub usage: UsageLedger,

    /// Budgetary limits for this agent.
    pub budget: AgentBudget,
}

impl Agent {
    /// Creates a new `Agent` with the given identity, backend, capabilities,
    /// and budget.
    ///
    /// The agent is initialised in the [`Idle`](AgentStatus::Idle) status with
    /// an empty transcript, no active run, no pending tools, no children, and
    /// an empty usage ledger.
    pub fn new(
        id: AgentId,
        session_id: SessionId,
        parent_id: Option<AgentId>,
        system_prompt: String,
        backend: BackendBinding,
        capabilities: AgentCapabilities,
        budget: AgentBudget,
    ) -> Self {
        Self {
            id,
            session_id,
            parent_id,
            state: AgentState {
                status: AgentStatus::Idle,
                current_operation: None,
                system_prompt,
                messages: Vec::new(),
                active_run: None,
                pending_tools: std::collections::HashMap::new(),
                children: Vec::new(),
                last_error: None,
            },
            backend,
            capabilities,
            usage: UsageLedger::default(),
            budget,
        }
    }

    /// Returns `true` if this agent is a root agent (has no parent).
    ///
    /// Root agents are created directly by a session.  Non-root agents are
    /// spawned by another agent as children.
    ///
    /// # Examples
    ///
    /// ```
    /// use harness_protocol::ids::AgentId;
    /// // A root agent has parent_id: None
    /// assert!(AgentId::new() != AgentId::new()); // just a demo
    /// ```
    pub fn is_root(&self) -> bool {
        self.parent_id.is_none()
    }
}

