// ---------------------------------------------------------------------------

#[cfg(test)]
mod tests {
    use std::collections::HashMap;

    use harness_protocol::backend::{
        BackendBinding, BackendCapabilities, BackendDescriptor, BackendReference,
    };
    use harness_protocol::commands::AgentStatus;
    use harness_protocol::ids::{AgentId, BackendId, ConfigurationId, IntegrationId, SessionId, ToolId};
    use harness_protocol::tools::{
        AgentToolset, PermissionMode, ToolCapability, ToolDescriptor, ToolPolicy,
    };
    use harness_protocol::usage::AgentBudget;

    use super::*;

    /// Creates a minimal `AgentCapabilities` for testing.
    fn test_capabilities() -> AgentCapabilities {
        let tool_id = ToolId::new();
        let mut tools = HashMap::new();
        tools.insert(
            tool_id,
            ToolCapability {
                descriptor: ToolDescriptor {
                    id: tool_id,
                    name: "test-tool".into(),
                    description: "A test tool".into(),
                    input_schema: serde_json::json!({}),
                },
                policy: ToolPolicy {
                    permission: PermissionMode::Allow,
                    enabled: true,
                },
                delegatable: true,
            },
        );

        AgentCapabilities {
            tools: AgentToolset { tools },
            can_spawn_agents: true,
            max_child_depth: Some(5),
            workspace: WorkspaceCapabilities {
                can_read: true,
                can_write: false,
                can_search: false,
            },
            backend: BackendCapabilities {
                tool_calls: true,
                ..Default::default()
            },
        }
    }

    /// Creates a minimal `BackendBinding` for testing.
    fn test_backend() -> BackendBinding {
        BackendBinding {
            reference: BackendReference {
                integration: IntegrationId::new(),
                configuration: ConfigurationId::new(),
                model: None,
            },
            descriptor: BackendDescriptor {
                id: BackendId::new(),
                name: "test-backend".into(),
                description: "Test backend".into(),
                capabilities: BackendCapabilities {
                    tool_calls: true,
                    ..Default::default()
                },
            },
        }
    }

    /// Creates a root agent (parent_id: None) with test defaults.
    fn create_root_agent() -> Agent {
        Agent::new(
            AgentId::new(),
            SessionId::new(),
            None, // root
            "You are a helpful assistant.".to_string(),
            test_backend(),
            test_capabilities(),
            AgentBudget {
                max_total_tokens: Some(100_000),
                ..Default::default()
            },
        )
    }

    /// Creates a child agent (parent_id: Some) with test defaults.
    fn create_child_agent(parent_id: AgentId) -> Agent {
        Agent::new(
            AgentId::new(),
            SessionId::new(),
            Some(parent_id),
            "You are a helpful assistant (child).".to_string(),
            test_backend(),
            test_capabilities(),
            AgentBudget {
                max_total_tokens: Some(50_000),
                ..Default::default()
            },
        )
    }

    // -----------------------------------------------------------------------
    // Construction
    // -----------------------------------------------------------------------

    #[test]
    fn root_agent_construction() {
        let agent = create_root_agent();
        assert_eq!(agent.state.status, AgentStatus::Idle);
        assert!(agent.state.messages.is_empty());
        assert!(agent.state.pending_tools.is_empty());
        assert!(agent.state.active_run.is_none());
        assert!(agent.state.children.is_empty());
        assert!(agent.state.last_error.is_none());
        assert!(agent.state.current_operation.is_none());
        assert!(agent.usage.records.is_empty());
    }

    #[test]
    fn child_agent_construction() {
        let parent_id = AgentId::new();
        let agent = create_child_agent(parent_id);
        assert_eq!(agent.state.status, AgentStatus::Idle);
        assert_eq!(agent.parent_id, Some(parent_id));
        assert!(agent.state.messages.is_empty());
        assert!(agent.usage.records.is_empty());
    }

    // -----------------------------------------------------------------------
    // is_root
    // -----------------------------------------------------------------------

    #[test]
    fn root_agent_is_root() {
        let agent = create_root_agent();
        assert!(agent.is_root(), "root agent should report is_root() == true");
    }

    #[test]
    fn child_agent_is_not_root() {
        let parent_id = AgentId::new();
        let agent = create_child_agent(parent_id);
        assert!(!agent.is_root(), "child agent should report is_root() == false");
    }

    #[test]
    fn multiple_children_all_not_root() {
        let root = create_root_agent();
        assert!(root.is_root());

        let child1 = create_child_agent(root.id);
        assert!(!child1.is_root());

        let child2 = create_child_agent(root.id);
        assert!(!child2.is_root());

        // Grandchild: child of child1
        let grandchild = create_child_agent(child1.id);
        assert!(!grandchild.is_root());
    }
}

