    fn create_child_agent(parent_id: AgentId) -> Agent {
        Agent::new(
            AgentId::new(),
            SessionId::new(),
            Some(parent_id),
            "You are a helpful assistant (child).".to_string(),
            test_backend(),
            test_capabilities(),
            AgentBudget {
                max_total_tokens: Some(50_000),
                ..Default::default()
            },
        )
    }

    // -----------------------------------------------------------------------
    // Construction
    // -----------------------------------------------------------------------

    #[test]
    fn root_agent_construction() {
        let agent = create_root_agent();
        assert_eq!(agent.state.status, AgentStatus::Idle);
        assert!(agent.state.messages.is_empty());
        assert!(agent.state.pending_tools.is_empty());
        assert!(agent.state.active_run.is_none());
        assert!(agent.state.children.is_empty());
        assert!(agent.state.last_error.is_none());
        assert!(agent.state.current_operation.is_none());
        assert!(agent.usage.records.is_empty());
    }

    #[test]
    fn child_agent_construction() {
        let parent_id = AgentId::new();
        let agent = create_child_agent(parent_id);
        assert_eq!(agent.state.status, AgentStatus::Idle);
        assert_eq!(agent.parent_id, Some(parent_id));
        assert!(agent.state.messages.is_empty());
        assert!(agent.usage.records.is_empty());
    }

    // -----------------------------------------------------------------------
    // is_root
    // -----------------------------------------------------------------------

    #[test]
    fn root_agent_is_root() {
        let agent = create_root_agent();
        assert!(agent.is_root(), "root agent should report is_root() == true");
    }

    #[test]
    fn child_agent_is_not_root() {
        let parent_id = AgentId::new();
        let agent = create_child_agent(parent_id);
        assert!(!agent.is_root(), "child agent should report is_root() == false");
    }

    #[test]
    fn multiple_children_all_not_root() {
        let root = create_root_agent();
        assert!(root.is_root());

        let child1 = create_child_agent(root.id);
        assert!(!child1.is_root());

        let child2 = create_child_agent(root.id);
        assert!(!child2.is_root());

        // Grandchild: child of child1
        let grandchild = create_child_agent(child1.id);
        assert!(!grandchild.is_root());
    }
}

