//! Agent domain entity for the harness core.
//!
//! This module defines [`Agent`] — the primary domain entity that owns state,
//! capabilities, usage, and budget.  An agent can be a root agent (no parent)
//! or a child/sub-agent spawned by another agent.
//!
//! # Lifecycle
//!
//! Agents are created via [`Agent::new`] and driven by commands via
//! [`Agent::apply`] (defined in `crate::transitions`).  They do **not**
//! perform I/O directly — instead they produce [`AgentEffect`]s that the
//! runtime interprets.

use harness_protocol::backend::{BackendBinding, BackendCapabilities};
use harness_protocol::commands::AgentStatus;
use harness_protocol::ids::{AgentId, SessionId};
use harness_protocol::tools::AgentToolset;
use harness_protocol::usage::AgentBudget;

use crate::agent_state::AgentState;
use crate::capabilities::{AgentCapabilities, WorkspaceCapabilities};

// ---------------------------------------------------------------------------
// UsageLedger
// ---------------------------------------------------------------------------

/// A ledger of usage records for an agent.
///
/// This is a minimal placeholder that will be extended with aggregation
/// methods (self-usage, descendant-usage, tree-sum) in a follow-up task.
#[derive(Debug, Clone, Default)]
pub struct UsageLedger {
    /// The ordered list of usage records accumulated by this agent.
    pub records: Vec<harness_protocol::usage::UsageRecord>,
}

// ---------------------------------------------------------------------------
// Agent
// ---------------------------------------------------------------------------

/// An independent reasoning worker — the primary domain entity of the harness.
///
/// An agent owns:
/// - Identity (`id`, `session_id`, `parent_id`)
/// - State (`status`, transcript, pending tool calls, children, errors)
/// - Backend binding (which backend to use, how to reach it)
/// - Capabilities (what tools, operations, and permissions the agent has)
/// - Usage tracking (token counts, cost)
/// - Budget constraints (limits on tokens, cost, children)
///
/// Agents form a tree: a session has one root agent, and root agents may spawn
/// child agents.  Every agent (root or child) is a full `Agent` instance —
/// there is no separate `SubAgent` type.
#[derive(Debug, Clone)]
pub struct Agent {
    /// Unique identifier for this agent.
    pub id: AgentId,
    /// The session this agent belongs to.
    pub session_id: SessionId,
    /// The parent agent, if any (root agents have `None`).
    pub parent_id: Option<AgentId>,

    /// The agent's mutable state (status, transcript, pending tools, etc.).
    pub state: AgentState,

    /// The backend binding — a reference + descriptor identifying which
    /// execution backend this agent uses.
    pub backend: BackendBinding,

    /// The capabilities granted to this agent (tools, spawn permissions, etc.).
    pub capabilities: AgentCapabilities,

    /// The accumulated usage ledger for this agent (does **not** include
    /// descendant usage — that is aggregated separately).
    pub usage: UsageLedger,

    /// Budgetary limits for this agent.
    pub budget: AgentBudget,
}

impl Agent {
    /// Creates a new `Agent` with the given identity, backend, capabilities,
    /// and budget.
    ///
    /// The agent is initialised in the [`Idle`](AgentStatus::Idle) status with
    /// an empty transcript, no active run, no pending tools, no children, and
    /// an empty usage ledger.
    pub fn new(
        id: AgentId,
        session_id: SessionId,
        parent_id: Option<AgentId>,
        system_prompt: String,
        backend: BackendBinding,
        capabilities: AgentCapabilities,
        budget: AgentBudget,
    ) -> Self {
        Self {
            id,
            session_id,
            parent_id,
            state: AgentState {
                status: AgentStatus::Idle,
                current_operation: None,
                system_prompt,
                messages: Vec::new(),
                active_run: None,
                pending_tools: std::collections::HashMap::new(),
                children: Vec::new(),
                last_error: None,
            },
            backend,
            capabilities,
            usage: UsageLedger::default(),
            budget,
        }
    }

    /// Returns `true` if this agent is a root agent (has no parent).
    ///
    /// Root agents are created directly by a session.  Non-root agents are
    /// spawned by another agent as children.
    ///
    /// # Examples
    ///
    /// ```
    /// use harness_protocol::ids::AgentId;
    /// // A root agent has parent_id: None
    /// assert!(AgentId::new() != AgentId::new()); // just a demo
    /// ```
    pub fn is_root(&self) -> bool {
        self.parent_id.is_none()
    }
}

