        assert!(agent.state.pending_tools.is_empty());
        assert!(agent.state.active_run.is_none());
        assert!(agent.state.children.is_empty());
        assert!(agent.state.last_error.is_none());
        assert!(agent.state.current_operation.is_none());
        assert!(agent.usage.records.is_empty());
    }

    #[test]
