        let parent_id = AgentId::new();
        let agent = create_child_agent(parent_id);
        assert_eq!(agent.state.status, AgentStatus::Idle);
        assert_eq!(agent.parent_id, Some(parent_id));
        assert!(agent.state.messages.is_empty());
        assert!(agent.usage.records.is_empty());
    }

