        let child1 = create_child_agent(root.id);
        assert!(!child1.is_root());

        let child2 = create_child_agent(root.id);
        assert!(!child2.is_root());

        // Grandchild: child of child1
        let grandchild = create_child_agent(child1.id);
        assert!(!grandchild.is_root());
    }
