#[cfg(test)]
mod tests {
    use harness_protocol::usage::{Cost, ModelUsage, UsageRecord, UsageValue};

    use super::*;

    // -----------------------------------------------------------------------
    // Helpers
    // -----------------------------------------------------------------------

    /// Creates a minimal `UsageRecord` with the given `input_tokens` value
    /// and all other fields set to unknown.
    fn record_with_input(input_tokens: u64) -> UsageRecord {
        UsageRecord {
            model_usage: ModelUsage {
                input_tokens: UsageValue::new(Some(input_tokens)),
                output_tokens: UsageValue::new(None),
                cache_read_tokens: UsageValue::new(None),
                cache_write_tokens: UsageValue::new(None),
                reasoning_tokens: UsageValue::new(None),
                total_tokens: UsageValue::new(None),
            },
            cost: Cost {
                amount_usd: None,
                source: None,
            },
            tool_usage: None,
        }
    }

    /// Creates a fully-unknown `ModelUsage` baseline.
    fn unknown_usage() -> ModelUsage {
        ModelUsage {
            input_tokens: UsageValue::new(None),
            output_tokens: UsageValue::new(None),
            cache_read_tokens: UsageValue::new(None),
            cache_write_tokens: UsageValue::new(None),
            reasoning_tokens: UsageValue::new(None),
            total_tokens: UsageValue::new(None),
        }
    }

    // -----------------------------------------------------------------------
    // UsageLedger basics
    // -----------------------------------------------------------------------

    #[test]
    fn empty_ledger_self_usage_is_all_unknown() {
        let ledger = UsageLedger::new();
        let usage = ledger.self_usage();

        assert!(usage.input_tokens.is_unknown());
        assert!(usage.output_tokens.is_unknown());
        assert!(usage.cache_read_tokens.is_unknown());
        assert!(usage.cache_write_tokens.is_unknown());
        assert!(usage.reasoning_tokens.is_unknown());
        assert!(usage.total_tokens.is_unknown());
    }

    #[test]
    fn ledger_with_one_record() {
        let mut ledger = UsageLedger::new();
        ledger.add_record(record_with_input(42));
        let usage = ledger.self_usage();

        assert_eq!(usage.input_tokens.value(), Some(42));
        // All other fields remain unknown because records only set input_tokens
        assert!(usage.output_tokens.is_unknown());
    }

    #[test]
    fn ledger_with_multiple_records_sums_input_tokens() {
        let mut ledger = UsageLedger::new();
        ledger.add_record(record_with_input(10));
        ledger.add_record(record_with_input(20));
        ledger.add_record(record_with_input(30));

        let usage = ledger.self_usage();
        assert_eq!(usage.input_tokens.value(), Some(60));
    }

    // -----------------------------------------------------------------------
    // Tree-sum without double-counting
    // -----------------------------------------------------------------------

    #[test]
    fn tree_sum_no_double_counting() {
        // --- Parent: 2 self records ---
        let mut parent_ledger = UsageLedger::new();
        parent_ledger.add_record(record_with_input(1));
        parent_ledger.add_record(record_with_input(1));

        // --- Child: 1 self record ---
        let mut child_ledger = UsageLedger::new();
        child_ledger.add_record(record_with_input(1));

        // Build child summary (leaf: no descendants)
        let child_summary = AgentUsageSummary {
            self_usage: child_ledger.self_usage(),
            descendant_usage: unknown_usage(),
            inclusive_usage: child_ledger.self_usage(), // leaf: self == inclusive
        };

        // Build parent summary via tree-sum
        let summary = compute_agent_usage_summary(&parent_ledger.records, &[child_summary]);

        // self_usage = parent's own 2 records
        assert_eq!(
            summary.self_usage.input_tokens.value(),
            Some(2),
            "parent self_usage should sum its own 2 records"
        );

        // descendant_usage = child's inclusive_usage (child has 1 record)
        assert_eq!(
            summary.descendant_usage.input_tokens.value(),
            Some(1),
            "descendant_usage should sum child inclusive_usage"
        );

        // inclusive_usage = self (2) + descendant (1) = 3
        assert_eq!(
            summary.inclusive_usage.input_tokens.value(),
            Some(3),
            "inclusive_usage should be self + descendant without double counting"
        );
    }

    // -----------------------------------------------------------------------
    // Unknown fields remain unknown through aggregation
    // -----------------------------------------------------------------------

    #[test]
    fn unknown_fields_remain_unknown_after_tree_sum() {
        let mut parent_ledger = UsageLedger::new();
        // Both records only set input_tokens; output_tokens and others stay unknown
        parent_ledger.add_record(record_with_input(5));
        parent_ledger.add_record(record_with_input(5));

        let mut child_ledger = UsageLedger::new();
        child_ledger.add_record(record_with_input(3));

        let child_summary = AgentUsageSummary {
            self_usage: child_ledger.self_usage(),
            descendant_usage: unknown_usage(),
            inclusive_usage: child_ledger.self_usage(),
        };

        let summary = compute_agent_usage_summary(&parent_ledger.records, &[child_summary]);

        // input_tokens is known (sum of all records)
        assert_eq!(summary.inclusive_usage.input_tokens.value(), Some(13));

        // output_tokens was never set → must remain unknown
        assert!(summary.self_usage.output_tokens.is_unknown());
        assert!(summary.descendant_usage.output_tokens.is_unknown());
        assert!(summary.inclusive_usage.output_tokens.is_unknown());

        // Similarly for cache_read, cache_write, reasoning, total
        assert!(summary.inclusive_usage.cache_read_tokens.is_unknown());
        assert!(summary.inclusive_usage.cache_write_tokens.is_unknown());
        assert!(summary.inclusive_usage.reasoning_tokens.is_unknown());
        assert!(summary.inclusive_usage.total_tokens.is_unknown());
    }

    // -----------------------------------------------------------------------
    // Partial unknown: one record has data, another doesn't
    // -----------------------------------------------------------------------

    #[test]
    fn partial_unknown_poisons_aggregate() {
        let mut ledger = UsageLedger::new();

        // First record: output_tokens is known (10)
        ledger.add_record(UsageRecord {
            model_usage: ModelUsage {
                input_tokens: UsageValue::new(Some(5)),
                output_tokens: UsageValue::new(Some(10)),
                cache_read_tokens: UsageValue::new(None),
                cache_write_tokens: UsageValue::new(None),
                reasoning_tokens: UsageValue::new(None),
                total_tokens: UsageValue::new(None),
            },
            cost: Cost {
                amount_usd: None,
                source: None,
            },
            tool_usage: None,
        });

        // Second record: output_tokens is unknown
        ledger.add_record(UsageRecord {
            model_usage: ModelUsage {
                input_tokens: UsageValue::new(Some(3)),
                output_tokens: UsageValue::new(None), // unknown
                cache_read_tokens: UsageValue::new(None),
                cache_write_tokens: UsageValue::new(None),
                reasoning_tokens: UsageValue::new(None),
                total_tokens: UsageValue::new(None),
            },
            cost: Cost {
                amount_usd: None,
                source: None,
            },
            tool_usage: None,
        });

        let usage = ledger.self_usage();

        // input_tokens: both known → sum
        assert_eq!(usage.input_tokens.value(), Some(8));

        // output_tokens: known + unknown → unknown (poisoned)
        assert!(usage.output_tokens.is_unknown());
    }
