#[test]
fn unknown_usage_stays_none_through_a_full_run() {
    let mut agent = create_test_agent();

    // Step 1: StartRun
    let _effects = agent.apply(AgentCommand::StartRun {
        input: UserInput {
            text: "Do something".into(),
            attachments: vec![],
        },
    });
    let run_id = agent.state.active_run.expect("run_id must be set");

    // Step 2: Receive a UsageUpdate with ALL fields unknown (None)
    let _effects = agent.apply(AgentCommand::BackendEvent {
        run_id,
        event: ExecutionEvent::UsageUpdate {
            request_id: RequestId::new(),
            usage: ModelUsage {
                input_tokens: UsageValue::new(None),
                output_tokens: UsageValue::new(None),
                cache_read_tokens: UsageValue::new(None),
                cache_write_tokens: UsageValue::new(None),
                reasoning_tokens: UsageValue::new(None),
                total_tokens: UsageValue::new(None),
            },
        },
    });

    // Step 3: Complete the run with usage having SOME fields unknown
    let _effects = agent.apply(AgentCommand::BackendEvent {
        run_id,
        event: ExecutionEvent::Completed {
            request_id: RequestId::new(),
            result: make_result(Some(10), None, Some(35)),
        },
    });

    // After completion, inspect the usage ledger
    let records = &agent.usage.records;

    // We should have 2 records (UsageUpdate + Completed)
    assert_eq!(records.len(), 2, "expected 2 usage records");

    // First record: all unknown
    assert!(
        records[0].model_usage.input_tokens.is_unknown(),
        "first record input_tokens must be unknown"
    );
    assert!(
        records[0].model_usage.output_tokens.is_unknown(),
        "first record output_tokens must be unknown"
    );
    assert!(
        records[0].model_usage.total_tokens.is_unknown(),
        "first record total_tokens must be unknown"
    );

    // Second record: input_tokens known (10), output_tokens unknown,
    // total_tokens known (35)
    assert_eq!(
        records[1].model_usage.input_tokens.value(),
        Some(10),
        "second record input_tokens should be Some(10)"
    );
    assert!(
        records[1].model_usage.output_tokens.is_unknown(),
        "second record output_tokens must stay unknown"
    );
    assert_eq!(
        records[1].model_usage.total_tokens.value(),
        Some(35),
        "second record total_tokens should be Some(35)"
    );

    // Critical invariant: if we aggregate, the output_tokens should remain
    // unknown because both records had it unknown — checked_add(None, None)
    // = None.
    let aggregated_output = records
        .iter()
        .fold(UsageValue::new(None), |acc, r| {
            acc.checked_add(r.model_usage.output_tokens)
        });
    assert!(
        aggregated_output.is_unknown(),
        "aggregated output_tokens must remain unknown through full run"
    );

    // Final state must be Idle
    assert_eq!(agent.state.status, AgentStatus::Idle);
}

