#[test]
fn scripted_vertical_slice() {
    let mut agent = create_test_agent();
    let tool_call_id = ToolCallId::new();

    // ------------------------------------------------------------------
    // Step 1: StartRun
    // ------------------------------------------------------------------
    let effects_1 = agent.apply(AgentCommand::StartRun {
        input: UserInput {
            text: "Help me with something".into(),
            attachments: vec![],
        },
    });

    // State assertions after StartRun
    assert_eq!(
        agent.state.status,
        AgentStatus::PreparingContext,
        "after StartRun: status should be PreparingContext"
    );
    let run_id = agent
        .state
        .active_run
        .expect("run_id must be set after StartRun");
    assert!(
        agent.state.pending_tools.is_empty(),
        "no pending tools after StartRun"
    );
    assert!(
        agent.state.messages.is_empty(),
        "transcript empty after StartRun"
    );

    // Effect assertions after StartRun
    assert_eq!(effects_1.len(), 3, "StartRun should produce exactly 3 effects");

    let has_state_changed = effects_1.iter().any(|e| {
        matches!(
            e,
            AgentEffect::Emit {
                event: AgentEvent::StateChanged {
                    from: AgentStatus::Idle,
                    to: AgentStatus::PreparingContext,
                },
            }
        )
    });
    assert!(
        has_state_changed,
        "effect[0]: StateChanged(Idle -> PreparingContext)"
    );

    let has_execute_backend = effects_1
        .iter()
        .any(|e| matches!(e, AgentEffect::ExecuteBackend { .. }));
    assert!(has_execute_backend, "effect[1]: ExecuteBackend");

    let has_run_started = effects_1.iter().any(|e| {
        matches!(
            e,
            AgentEffect::Emit {
                event: AgentEvent::RunStarted { .. },
            }
        )
    });
    assert!(has_run_started, "effect[2]: RunStarted");

    // ------------------------------------------------------------------
    // Step 2: BackendEvent(ToolCallRequested)
    // ------------------------------------------------------------------
    let effects_2 = agent.apply(AgentCommand::BackendEvent {
        run_id,
        event: ExecutionEvent::ToolCallRequested {
            request_id: RequestId::new(),
            call: ToolCall {
                id: tool_call_id,
                name: "test-tool".into(),
                arguments: serde_json::json!({"input": "test"}),
            },
        },
    });

    // State assertions
    assert!(
        agent.state.pending_tools.contains_key(&tool_call_id),
        "tool_call should be pending"
    );
    assert_eq!(
        agent.state.pending_tools.len(),
        1,
        "exactly one pending tool"
    );
    assert_eq!(
        agent.state.status,
        AgentStatus::PreparingContext,
        "status unchanged by ToolCallRequested"
    );

    // Effect assertions: exactly 1 effect (ToolCallRequested event)
    assert_eq!(
        effects_2.len(),
        1,
        "ToolCallRequested should produce exactly 1 effect"
    );

    let has_tool_requested = effects_2.iter().any(|e| {
        matches!(
            e,
            AgentEffect::Emit {
                event: AgentEvent::ToolCallRequested { .. },
            }
        )
    });
    assert!(has_tool_requested, "effect: ToolCallRequested");

    // ------------------------------------------------------------------
    // Step 3: ToolCompleted
    // ------------------------------------------------------------------
    let effects_3 = agent.apply(AgentCommand::ToolCompleted {
        call_id: tool_call_id,
        result: ToolResult {
            call_id: tool_call_id,
            output: serde_json::json!({"result": "ok"}),
            is_error: false,
        },
    });

    // State assertions
    assert!(
        !agent.state.pending_tools.contains_key(&tool_call_id),
        "tool call removed from pending"
    );
    assert!(
        agent.state.pending_tools.is_empty(),
        "no pending tools remain"
    );
    assert_eq!(
        agent.state.messages.len(),
        1,
        "one tool result message appended to transcript"
    );
    assert_eq!(
        agent.state.messages[0].role,
        harness_protocol::messages::MessageRole::Tool,
        "appended message must have Tool role"
    );
    assert_eq!(
        agent.state.status,
        AgentStatus::WaitingForBackend,
        "status transitions to WaitingForBackend after all tools complete"
    );

    // Effect assertions: ToolCallCompleted + ExecuteBackend
    assert_eq!(
        effects_3.len(),
        2,
        "ToolCompleted should produce exactly 2 effects"
    );

    let has_tool_completed = effects_3.iter().any(|e| {
        matches!(
            e,
            AgentEffect::Emit {
                event: AgentEvent::ToolCallCompleted {
                    call_id,
                    result,
                },
            } if *call_id == tool_call_id && !result.has_error
        )
    });
    assert!(
        has_tool_completed,
        "effect[0]: ToolCallCompleted with has_error=false"
    );

    let has_next_backend = effects_3
        .iter()
        .any(|e| matches!(e, AgentEffect::ExecuteBackend { .. }));
    assert!(
        has_next_backend,
        "effect[1]: ExecuteBackend to continue run"
    );

    // ------------------------------------------------------------------
    // Step 4: BackendEvent(UsageUpdate) with partially-known usage
    // ------------------------------------------------------------------
    let _effects_usage = agent.apply(AgentCommand::BackendEvent {
        run_id,
        event: ExecutionEvent::UsageUpdate {
            request_id: RequestId::new(),
            usage: ModelUsage {
                input_tokens: UsageValue::new(Some(5)),
                output_tokens: UsageValue::new(Some(10)),
                cache_read_tokens: UsageValue::new(None),
                cache_write_tokens: UsageValue::new(None),
                reasoning_tokens: UsageValue::new(None),
                total_tokens: UsageValue::new(Some(15)),
            },
        },
    });

    // UsageUpdate produces no effects (returns vec![])
    // But it mutates the usage ledger
    assert_eq!(
        agent.usage.records.len(),
        1,
        "one usage record after UsageUpdate"
    );

    // ------------------------------------------------------------------
    // Step 5: BackendEvent(Completed)
    // ------------------------------------------------------------------
    let final_usage = ModelUsage {
        input_tokens: UsageValue::new(Some(10)),
        output_tokens: UsageValue::new(Some(20)),
        cache_read_tokens: UsageValue::new(None),
        cache_write_tokens: UsageValue::new(None),
        reasoning_tokens: UsageValue::new(Some(5)),
        total_tokens: UsageValue::new(Some(35)),
    };

    let effects_4 = agent.apply(AgentCommand::BackendEvent {
        run_id,
        event: ExecutionEvent::Completed {
            request_id: RequestId::new(),
            result: ExecutionResult {
                request_id: RequestId::new(),
                usage: final_usage.clone(),
                cost: Cost {
                    amount_usd: None,
                    source: None,
                },
                finish_reason: "end_turn".into(),
            },
        },
    });

    // Final state assertions
    assert_eq!(
        agent.state.status,
        AgentStatus::Idle,
        "after Completed: status returns to Idle"
    );
    assert!(
        agent.state.active_run.is_none(),
        "active_run cleared after completion"
    );
    assert!(
        agent.state.pending_tools.is_empty(),
        "no pending tools at end"
    );

    // Usage ledger should have 2 records (UsageUpdate + Completed)
    assert_eq!(
        agent.usage.records.len(),
        2,
        "two usage records: UsageUpdate + Completed"
    );

    // Verify the final usage record has the correct values
    let final_record = &agent.usage.records[1];
    assert_eq!(
        final_record.model_usage.input_tokens.value(),
        Some(10),
        "final input_tokens"
    );
    assert_eq!(
        final_record.model_usage.output_tokens.value(),
        Some(20),
        "final output_tokens"
    );
    assert!(
        final_record.model_usage.cache_read_tokens.is_unknown(),
        "cache_read_tokens stays unknown"
    );
    assert!(
        final_record.model_usage.cache_write_tokens.is_unknown(),
        "cache_write_tokens stays unknown"
    );
    assert_eq!(
        final_record.model_usage.reasoning_tokens.value(),
        Some(5),
        "final reasoning_tokens"
    );
    assert_eq!(
        final_record.model_usage.total_tokens.value(),
        Some(35),
        "final total_tokens"
    );

    // Effect assertions after Completed
    assert_eq!(effects_4.len(), 3, "Completed should produce exactly 3 effects");

    let has_final_state_changed = effects_4.iter().any(|e| {
        matches!(
            e,
            AgentEffect::Emit {
                event: AgentEvent::StateChanged {
                    from: AgentStatus::WaitingForBackend,
                    to: AgentStatus::Idle,
                },
            }
        )
    });
    assert!(
        has_final_state_changed,
        "effect[0]: StateChanged(WaitingForBackend -> Idle)"
    );

    let has_completed_event = effects_4.iter().any(|e| {
        matches!(
            e,
            AgentEffect::Emit {
                event: AgentEvent::Completed {
                    outcome: AgentOutcome::Success,
                },
            }
        )
    });
    assert!(has_completed_event, "effect[1]: Completed(Success)");

    let has_finish_run = effects_4
        .iter()
        .any(|e| matches!(e, AgentEffect::FinishRun { .. }));
    assert!(has_finish_run, "effect[2]: FinishRun");

    // ------------------------------------------------------------------
    // Verify the "unknown is not zero" invariant through the full run
    // ------------------------------------------------------------------
    // The UsageUpdate had output_tokens=Some(10), the Completed had
    // output_tokens=Some(20). Both are known, so aggregating should
    // give Some(30).
    let agg_output = agent
        .usage
        .records
        .iter()
        .fold(UsageValue::new(None), |acc, r| {
            acc.checked_add(r.model_usage.output_tokens)
        });
    assert_eq!(
        agg_output.value(),
        Some(30),
        "aggregated output_tokens should be sum of known values"
    );

    // cache_write_tokens was never reported — must stay unknown
    let agg_cache_write = agent
        .usage
        .records
        .iter()
        .fold(UsageValue::new(None), |acc, r| {
            acc.checked_add(r.model_usage.cache_write_tokens)
        });
    assert!(
        agg_cache_write.is_unknown(),
        "cache_write_tokens must stay unknown through entire run"
    );
}

