// The core "unknown != zero" type
#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
pub struct UsageValue(Option<u64>);

impl UsageValue {
    pub fn new(v: Option<u64>) -> Self { Self(v) }
    pub fn is_unknown(&self) -> bool { self.0.is_none() }
    pub fn is_zero(&self) -> bool { self.0 == Some(0) }
    pub fn value(&self) -> Option<u64> { self.0 }

    /// Only returns Some if BOTH values are Some (addition).
    /// If either is None, result stays None — the invariant.
    pub fn checked_add(self, other: Self) -> Self {
        match (self.0, other.0) {
            (Some(a), Some(b)) => Self(Some(a + b)),
            _ => Self(None),
        }
    }
}

