use harness_protocol::{UsageRecord, UsageLedger, ModelUsage, AgentUsageSummary};
use std::collections::HashMap;

impl UsageLedger {
    pub fn new() -> Self { UsageLedger { records: Vec::new() } }

    pub fn add_record(&mut self, record: UsageRecord) {
        self.records.push(record);
    }

    /// Self-usage: aggregation of THIS ledger's records only.
    pub fn self_usage(&self) -> ModelUsage {
        self.aggregate(&self.records)
    }

    /// Aggregate a set of records into a single ModelUsage.
    /// The "unknown is not zero" invariant is preserved.
    fn aggregate(&self, records: &[UsageRecord]) -> ModelUsage {
        let mut result = ModelUsage::default();
        for record in records {
            result = ModelUsage {
                input_tokens: result.input_tokens.checked_add(record.usage.input_tokens),
                output_tokens: result.output_tokens.checked_add(record.usage.output_tokens),
                // ... same for all fields
                ..result
            };
        }
        result
    }
}

/// Tree-sum aggregation: takes a parent ledger and child summaries.
pub fn compute_agent_usage_summary(
    self_records: &[UsageRecord],
    child_summaries: &[AgentUsageSummary],
) -> AgentUsageSummary {
    let self_usage = UsageLedger { records: self_records.to_vec() }.self_usage();

    let mut descendant_usage = ModelUsage::default();
    for child in child_summaries {
        descendant_usage = ModelUsage {
            input_tokens: descendant_usage.input_tokens.checked_add(
                child.inclusive_usage.input_tokens
            ),
            // ... all fields
            ..descendant_usage
        };
    }

    let inclusive_usage = ModelUsage {
        input_tokens: self_usage.input_tokens.checked_add(descendant_usage.input_tokens),
        // ... all fields
        ..ModelUsage::default()
    };

    AgentUsageSummary {
        self_usage,
        descendant_usage,
        inclusive_usage,
    }
}
```

**Tests:**
1. Parent has 2 self records, child has 1 record. `inclusive_usage` sums all three, `self_usage` only the parent's 2, `descendant_usage` only the child's 1.
2. No double counting when `compute_agent_usage_summary` is called twice.
3. Unknown fields remain unknown through aggregation.

**Acceptance:** Tree-sum without double-counting; "unknown is not zero" preserved.

