#![warn(clippy::all)]

//! Shared IDs, commands, events, and serializable protocol types; no runtime or I/O policy.

pub mod backend;
pub mod commands;
pub mod effects;
pub mod events;
pub mod ids;
pub mod messages;
pub mod tools;
pub mod usage;

#![warn(clippy::all)]

//! Deterministic Agent/Session domain semantics: state, transitions, commands, and effects. No I/O.

pub mod agent;
pub mod agent_state;
pub mod budget;
pub mod capabilities;
pub mod transcript;
pub mod transitions;
pub mod usage;

//! Agent domain entity for the harness core.
//!
//! This module defines [`Agent`] — the primary domain entity that owns state,
//! capabilities, usage, and budget.  An agent can be a root agent (no parent)
//! or a child/sub-agent spawned by another agent.
//!
//! # Lifecycle
//!
//! Agents are created via [`Agent::new`] and driven by commands via
//! [`Agent::apply`] (defined in `crate::transitions`).  They do **not**
//! perform I/O directly — instead they produce [`AgentEffect`]s that the
//! runtime interprets.

use harness_protocol::backend::{BackendBinding, BackendCapabilities};
use harness_protocol::commands::AgentStatus;
use harness_protocol::ids::{AgentId, SessionId};
use harness_protocol::tools::AgentToolset;
use harness_protocol::usage::AgentBudget;

use crate::agent_state::AgentState;
use crate::capabilities::{AgentCapabilities, WorkspaceCapabilities};

// ---------------------------------------------------------------------------
// UsageLedger
// ---------------------------------------------------------------------------

/// A ledger of usage records for an agent.
///
/// This is a minimal placeholder that will be extended with aggregation
/// methods (self-usage, descendant-usage, tree-sum) in a follow-up task.
#[derive(Debug, Clone, Default)]
pub struct UsageLedger {
    /// The ordered list of usage records accumulated by this agent.
    pub records: Vec<harness_protocol::usage::UsageRecord>,
}

// ---------------------------------------------------------------------------
// Agent
// ---------------------------------------------------------------------------

/// An independent reasoning worker — the primary domain entity of the harness.
///
/// An agent owns:
/// - Identity (`id`, `session_id`, `parent_id`)
/// - State (`status`, transcript, pending tool calls, children, errors)
/// - Backend binding (which backend to use, how to reach it)
/// - Capabilities (what tools, operations, and permissions the agent has)
/// - Usage tracking (token counts, cost)
/// - Budget constraints (limits on tokens, cost, children)
///
/// Agents form a tree: a session has one root agent, and root agents may spawn
/// child agents.  Every agent (root or child) is a full `Agent` instance —
/// there is no separate `SubAgent` type.
#[derive(Debug, Clone)]
pub struct Agent {
    /// Unique identifier for this agent.
    pub id: AgentId,
    /// The session this agent belongs to.
    pub session_id: SessionId,
    /// The parent agent, if any (root agents have `None`).
    pub parent_id: Option<AgentId>,

    /// The agent's mutable state (status, transcript, pending tools, etc.).
    pub state: AgentState,

    /// The backend binding — a reference + descriptor identifying which
    /// execution backend this agent uses.
    pub backend: BackendBinding,

    /// The capabilities granted to this agent (tools, spawn permissions, etc.).
    pub capabilities: AgentCapabilities,

    /// The accumulated usage ledger for this agent (does **not** include
    /// descendant usage — that is aggregated separately).
    pub usage: UsageLedger,

    /// Budgetary limits for this agent.
    pub budget: AgentBudget,
}

impl Agent {
    /// Creates a new `Agent` with the given identity, backend, capabilities,
    /// and budget.
    ///
    /// The agent is initialised in the [`Idle`](AgentStatus::Idle) status with
    /// an empty transcript, no active run, no pending tools, no children, and
    /// an empty usage ledger.
    pub fn new(
        id: AgentId,
        session_id: SessionId,
        parent_id: Option<AgentId>,
        system_prompt: String,
        backend: BackendBinding,
        capabilities: AgentCapabilities,
        budget: AgentBudget,
    ) -> Self {
        Self {
            id,
            session_id,
            parent_id,
            state: AgentState {
                status: AgentStatus::Idle,
                current_operation: None,
                system_prompt,
                messages: Vec::new(),
                active_run: None,
                pending_tools: std::collections::HashMap::new(),
                children: Vec::new(),
                last_error: None,
            },
            backend,
            capabilities,
            usage: UsageLedger::default(),
            budget,
        }
    }

    /// Returns `true` if this agent is a root agent (has no parent).
    ///
    /// Root agents are created directly by a session.  Non-root agents are
    /// spawned by another agent as children.
    ///
    /// # Examples
    ///
    /// ```
    /// use harness_protocol::ids::AgentId;
    /// // A root agent has parent_id: None
    /// assert!(AgentId::new() != AgentId::new()); // just a demo
    /// ```
    pub fn is_root(&self) -> bool {
        self.parent_id.is_none()
    }
}

// ---------------------------------------------------------------------------
// Tests
// ---------------------------------------------------------------------------

#[cfg(test)]
mod tests {
    use std::collections::HashMap;

    use harness_protocol::backend::{
        BackendBinding, BackendCapabilities, BackendDescriptor, BackendReference,
    };
    use harness_protocol::commands::AgentStatus;
    use harness_protocol::ids::{AgentId, BackendId, ConfigurationId, IntegrationId, SessionId, ToolId};
    use harness_protocol::tools::{
        AgentToolset, PermissionMode, ToolCapability, ToolDescriptor, ToolPolicy,
    };
    use harness_protocol::usage::AgentBudget;

    use super::*;

    /// Creates a minimal `AgentCapabilities` for testing.
    fn test_capabilities() -> AgentCapabilities {
        let tool_id = ToolId::new();
        let mut tools = HashMap::new();
        tools.insert(
            tool_id,
            ToolCapability {
                descriptor: ToolDescriptor {
                    id: tool_id,
                    name: "test-tool".into(),
                    description: "A test tool".into(),
                    input_schema: serde_json::json!({}),
                },
                policy: ToolPolicy {
                    permission: PermissionMode::Allow,
                    enabled: true,
                },
                delegatable: true,
            },
        );

        AgentCapabilities {
            tools: AgentToolset { tools },
            can_spawn_agents: true,
            max_child_depth: Some(5),
            workspace: WorkspaceCapabilities {
                can_read: true,
                can_write: false,
                can_search: false,
            },
            backend: BackendCapabilities {
                tool_calls: true,
                ..Default::default()
            },
        }
    }

    /// Creates a minimal `BackendBinding` for testing.
    fn test_backend() -> BackendBinding {
        BackendBinding {
            reference: BackendReference {
                integration: IntegrationId::new(),
                configuration: ConfigurationId::new(),
                model: None,
            },
            descriptor: BackendDescriptor {
                id: BackendId::new(),
                name: "test-backend".into(),
                description: "Test backend".into(),
                capabilities: BackendCapabilities {
                    tool_calls: true,
                    ..Default::default()
                },
            },
        }
    }

    /// Creates a root agent (parent_id: None) with test defaults.
    fn create_root_agent() -> Agent {
        Agent::new(
            AgentId::new(),
            SessionId::new(),
            None, // root
            "You are a helpful assistant.".to_string(),
            test_backend(),
            test_capabilities(),
            AgentBudget {
                max_total_tokens: Some(100_000),
                ..Default::default()
            },
        )
    }

    /// Creates a child agent (parent_id: Some) with test defaults.
    fn create_child_agent(parent_id: AgentId) -> Agent {
        Agent::new(
            AgentId::new(),
            SessionId::new(),
            Some(parent_id),
            "You are a helpful assistant (child).".to_string(),
            test_backend(),
            test_capabilities(),
            AgentBudget {
                max_total_tokens: Some(50_000),
                ..Default::default()
            },
        )
    }

    // -----------------------------------------------------------------------
    // Construction
    // -----------------------------------------------------------------------

    #[test]
    fn root_agent_construction() {
        let agent = create_root_agent();
        assert_eq!(agent.state.status, AgentStatus::Idle);
        assert!(agent.state.messages.is_empty());
        assert!(agent.state.pending_tools.is_empty());
        assert!(agent.state.active_run.is_none());
        assert!(agent.state.children.is_empty());
        assert!(agent.state.last_error.is_none());
        assert!(agent.state.current_operation.is_none());
        assert!(agent.usage.records.is_empty());
    }

    #[test]
    fn child_agent_construction() {
        let parent_id = AgentId::new();
        let agent = create_child_agent(parent_id);
        assert_eq!(agent.state.status, AgentStatus::Idle);
        assert_eq!(agent.parent_id, Some(parent_id));
        assert!(agent.state.messages.is_empty());
        assert!(agent.usage.records.is_empty());
    }

    // -----------------------------------------------------------------------
    // is_root
    // -----------------------------------------------------------------------

    #[test]
    fn root_agent_is_root() {
        let agent = create_root_agent();
        assert!(agent.is_root(), "root agent should report is_root() == true");
    }

    #[test]
    fn child_agent_is_not_root() {
        let parent_id = AgentId::new();
        let agent = create_child_agent(parent_id);
        assert!(!agent.is_root(), "child agent should report is_root() == false");
    }

    #[test]
    fn multiple_children_all_not_root() {
        let root = create_root_agent();
        assert!(root.is_root());

        let child1 = create_child_agent(root.id);
        assert!(!child1.is_root());

        let child2 = create_child_agent(root.id);
        assert!(!child2.is_root());

        // Grandchild: child of child1
        let grandchild = create_child_agent(child1.id);
        assert!(!grandchild.is_root());
    }
}

