//! Agent capabilities and non-escalation enforcement.
//!
//! This module defines how an agent's permissions are represented
//! ([`AgentCapabilities`], [`WorkspaceCapabilities`]) and how child
//! capabilities are derived from a parent while enforcing the
//! **non-escalation invariant** (spec §23):
//!
//! > `ChildTools ⊆ ParentDelegatableTools`
//!
//! The entry points are [`AgentCapabilities::can_delegate`] and
//! [`AgentCapabilities::derive_child_capabilities`].

use std::collections::HashMap;

use harness_protocol::backend::BackendCapabilities;
use harness_protocol::effects::ToolInheritance;
use harness_protocol::ids::ToolId;
use harness_protocol::tools::{AgentToolset, ToolCapability};

// ---------------------------------------------------------------------------
// WorkspaceCapabilities
// ---------------------------------------------------------------------------

/// Declares what workspace operations an agent is permitted to perform.
#[derive(Debug, Clone)]
pub struct WorkspaceCapabilities {
    /// Whether the agent can read files from the workspace.
    pub can_read: bool,
    /// Whether the agent can write files to the workspace.
    pub can_write: bool,
    /// Whether the agent can search the workspace.
    pub can_search: bool,
}

// ---------------------------------------------------------------------------
// AgentCapabilities
// ---------------------------------------------------------------------------

/// The full set of capabilities granted to an agent.
///
/// This includes the tools the agent may use, whether it can spawn children,
/// its workspace permissions, and the capabilities advertised by its backend.
///
/// The sub-agent non-escalation invariant (spec §23) is enforced by
/// [`derive_child_capabilities`](AgentCapabilities::derive_child_capabilities).
#[derive(Debug, Clone)]
pub struct AgentCapabilities {
    /// The tools this agent is allowed to use.
    pub tools: AgentToolset,
    /// Whether this agent may spawn sub-agents.
    pub can_spawn_agents: bool,
    /// Maximum allowed nesting depth for children (`None` = unlimited).
    pub max_child_depth: Option<u32>,
    /// Workspace access permissions.
    pub workspace: WorkspaceCapabilities,
    /// Capabilities of the backend this agent is bound to (cached for quick lookup).
    pub backend: BackendCapabilities,
}

// ---------------------------------------------------------------------------
// CapabilityError
// ---------------------------------------------------------------------------

/// Errors that can occur when deriving child capabilities.
#[derive(Debug, Clone, thiserror::Error)]
pub enum CapabilityError {
    /// The requested tool does not exist in the parent's toolset.
    #[error("Tool {0} not found in parent capabilities")]
    ToolNotFound(ToolId),

    /// The requested tool exists but is not delegatable to children.
    #[error("Tool {0} is not delegatable")]
    NotDelegatable(ToolId),

    /// The requested tool is not enabled in the parent's toolset.
    #[error("Tool {0} is not enabled in parent")]
    NotEnabled(ToolId),
}

// ---------------------------------------------------------------------------
// Methods
// ---------------------------------------------------------------------------

impl AgentCapabilities {
    /// Returns `true` if the given tool can be delegated to a child agent.
    ///
    /// A tool is delegatable **only if** it exists in the current agent's
    /// toolset **and** both `delegatable` and `policy.enabled` are `true`.
    ///
    /// If the tool is not found at all, returns `false`.
    pub fn can_delegate(&self, tool_id: &ToolId) -> bool {
        self.tools
            .tools
            .get(tool_id)
            .map(|tc| tc.delegatable && tc.policy.enabled)
            .unwrap_or(false)
    }

    /// Derives a child's toolset from a parent's capabilities using the
    /// specified inheritance strategy.
    ///
    /// This method enforces the **non-escalation invariant**:
    ///
    /// > A child must never automatically obtain capabilities that the parent
    /// > cannot delegate.
    ///
    /// # Invariants enforced per variant
    ///
    /// | Variant | Invariant |
    /// |---|---|
    /// | `InheritAll` | Child gets all parent tools — no extra check needed because the parent already owns them. |
    /// | `Subset(ids)` | Every tool in the list must exist in the parent, be delegatable, and be enabled. |
    /// | `Replace(toolset)` | Every tool in the replacement set must be delegatable from the parent. |
    ///
    /// # Errors
    ///
    /// Returns [`CapabilityError::ToolNotFound`] if a requested tool does not
    /// exist in the parent. Returns [`CapabilityError::NotDelegatable`] if a
    /// requested tool is not delegatable. Returns [`CapabilityError::NotEnabled`]
    /// if a requested tool is not enabled.
    pub fn derive_child_capabilities(
        &self,
        inheritance: &ToolInheritance,
    ) -> Result<AgentToolset, CapabilityError> {
        let child_tools = match inheritance {
            ToolInheritance::InheritAll => self.tools.tools.clone(),

            ToolInheritance::Subset(ids) => {
                let mut tools = HashMap::new();
                for id in ids {
                    let capability = self
                        .tools
                        .tools
                        .get(id)
                        .ok_or_else(|| CapabilityError::ToolNotFound(*id))?;
                    if !capability.delegatable {
                        return Err(CapabilityError::NotDelegatable(*id));
                    }
                    if !capability.policy.enabled {
                        return Err(CapabilityError::NotEnabled(*id));
                    }
                    tools.insert(*id, capability.clone());
                }
                tools
            }

            ToolInheritance::Replace(toolset) => {
                for (id, _) in &toolset.tools {
                    if !self.can_delegate(id) {
                        return Err(CapabilityError::NotDelegatable(*id));
                    }
                }
                toolset.tools.clone()
            }
        };

        Ok(AgentToolset { tools: child_tools })
    }
}

// ---------------------------------------------------------------------------
// Tests
// ---------------------------------------------------------------------------

#[cfg(test)]
mod tests {
    use std::collections::HashMap;

    use harness_protocol::backend::BackendCapabilities;
    use harness_protocol::effects::ToolInheritance;
    use harness_protocol::ids::ToolId;
    use harness_protocol::tools::{
        AgentToolset, PermissionMode, ToolCapability, ToolDescriptor, ToolPolicy,
    };

    use super::*;

    // -----------------------------------------------------------------------
    // Helpers
    // -----------------------------------------------------------------------

    /// Creates an `AgentCapabilities` with a single delegatable, enabled tool.
    fn parent_with_one_delegatable_tool() -> AgentCapabilities {
        let tool_id = ToolId::new();
        let mut tools = HashMap::new();
        tools.insert(
            tool_id,
            ToolCapability {
                descriptor: ToolDescriptor {
                    id: tool_id,
                    name: "fs.read".into(),
                    description: "Read files".into(),
                    input_schema: serde_json::json!({}),
                },
                policy: ToolPolicy {
                    permission: PermissionMode::Allow,
                    enabled: true,
                },
                delegatable: true,
            },
        );

        AgentCapabilities {
            tools: AgentToolset { tools },
            can_spawn_agents: true,
            max_child_depth: Some(5),
            workspace: WorkspaceCapabilities {
                can_read: true,
                can_write: false,
                can_search: false,
            },
            backend: BackendCapabilities {
                tool_calls: true,
                ..Default::default()
            },
        }
    }

    /// Creates an `AgentCapabilities` with two tools:
    /// - `fs.read`    (delegatable, enabled)
    /// - `shell.exec` (not delegatable, enabled)
    fn parent_with_mixed_tools() -> (AgentCapabilities, ToolId, ToolId) {
        let fs_read_id = ToolId::new();
        let shell_exec_id = ToolId::new();
        let mut tools = HashMap::new();

        tools.insert(
            fs_read_id,
            ToolCapability {
                descriptor: ToolDescriptor {
                    id: fs_read_id,
                    name: "fs.read".into(),
                    description: "Read files".into(),
                    input_schema: serde_json::json!({}),
                },
                policy: ToolPolicy {
                    permission: PermissionMode::Allow,
                    enabled: true,
                },
                delegatable: true,
            },
        );

        tools.insert(
            shell_exec_id,
            ToolCapability {
                descriptor: ToolDescriptor {
                    id: shell_exec_id,
                    name: "shell.exec".into(),
                    description: "Execute shell commands".into(),
                    input_schema: serde_json::json!({}),
                },
                policy: ToolPolicy {
                    permission: PermissionMode::Allow,
                    enabled: true,
                },
                delegatable: false,
            },
        );

        let caps = AgentCapabilities {
            tools: AgentToolset { tools },
            can_spawn_agents: true,
            max_child_depth: Some(5),
            workspace: WorkspaceCapabilities {
                can_read: true,
                can_write: false,
                can_search: false,
            },
            backend: BackendCapabilities {
                tool_calls: true,
                ..Default::default()
            },
        };

        (caps, fs_read_id, shell_exec_id)
    }

    // -----------------------------------------------------------------------
    // can_delegate
    // -----------------------------------------------------------------------

    #[test]
    fn delegatable_enabled_tool_is_delegatable() {
        let caps = parent_with_one_delegatable_tool();
        let tool_id = *caps.tools.tools.keys().next().unwrap();
        assert!(caps.can_delegate(&tool_id));
    }

    #[test]
    fn non_delegatable_tool_is_not_delegatable() {
        let (caps, _fs_read_id, shell_exec_id) = parent_with_mixed_tools();
        assert!(!caps.can_delegate(&shell_exec_id));
    }

    #[test]
    fn non_existent_tool_is_not_delegatable() {
        let caps = parent_with_one_delegatable_tool();
        let unknown = ToolId::new();
        assert!(!caps.can_delegate(&unknown));
    }

    // -----------------------------------------------------------------------
    // derive_child_capabilities — InheritAll
    // -----------------------------------------------------------------------

    #[test]
    fn inherit_all_returns_all_parent_tools() {
        let caps = parent_with_one_delegatable_tool();
        let result = caps.derive_child_capabilities(&ToolInheritance::InheritAll);
        assert!(result.is_ok());
        let child_set = result.unwrap();
        assert_eq!(child_set.tools.len(), caps.tools.tools.len());
    }

    // -----------------------------------------------------------------------
    // derive_child_capabilities — Subset
    // -----------------------------------------------------------------------

    #[test]
    fn subset_with_all_delegatable_succeeds() {
        let (caps, fs_read_id, _) = parent_with_mixed_tools();
        let result = caps
            .derive_child_capabilities(&ToolInheritance::Subset(vec![fs_read_id]));
        assert!(result.is_ok());
        let child_set = result.unwrap();
        assert_eq!(child_set.tools.len(), 1);
        assert!(child_set.tools.contains_key(&fs_read_id));
    }

    #[test]
    fn subset_with_non_delegatable_is_rejected() {
        let (caps, _fs_read_id, shell_exec_id) = parent_with_mixed_tools();
        let result = caps.derive_child_capabilities(&ToolInheritance::Subset(vec![
            shell_exec_id,
        ]));
        assert!(result.is_err());
        match result {
            Err(CapabilityError::NotDelegatable(id)) => assert_eq!(id, shell_exec_id),
            other => panic!("expected NotDelegatable, got {other:?}"),
        }
    }

    #[test]
    fn subset_with_non_existent_tool_is_rejected() {
        let caps = parent_with_one_delegatable_tool();
        let unknown = ToolId::new();
        let result = caps
            .derive_child_capabilities(&ToolInheritance::Subset(vec![unknown]));
        assert!(result.is_err());
        match result {
            Err(CapabilityError::ToolNotFound(id)) => assert_eq!(id, unknown),
            other => panic!("expected ToolNotFound, got {other:?}"),
        }
    }

    #[test]
    fn subset_rejects_not_enabled_tool() {
        let tool_id = ToolId::new();
        let mut tools = HashMap::new();
        tools.insert(
            tool_id,
            ToolCapability {
                descriptor: ToolDescriptor {
                    id: tool_id,
                    name: "disabled-tool".into(),
                    description: "A disabled tool".into(),
                    input_schema: serde_json::json!({}),
                },
                policy: ToolPolicy {
                    permission: PermissionMode::Deny,
                    enabled: false,
                },
                delegatable: true,
            },
        );

        let caps = AgentCapabilities {
            tools: AgentToolset { tools },
            can_spawn_agents: false,
            max_child_depth: None,
            workspace: WorkspaceCapabilities {
                can_read: false,
                can_write: false,
                can_search: false,
            },
            backend: BackendCapabilities::default(),
        };

        let result = caps
            .derive_child_capabilities(&ToolInheritance::Subset(vec![tool_id]));
        assert!(result.is_err());
        match result {
            Err(CapabilityError::NotEnabled(id)) => assert_eq!(id, tool_id),
            other => panic!("expected NotEnabled, got {other:?}"),
        }
    }

    // -----------------------------------------------------------------------
    // derive_child_capabilities — Replace
    // -----------------------------------------------------------------------

    #[test]
    fn replace_with_delegatable_tools_succeeds() {
        let caps = parent_with_one_delegatable_tool();
        let tool_id = *caps.tools.tools.keys().next().unwrap();

        // Build a replacement toolset with the same delegatable tool
        let mut replacement = HashMap::new();
        replacement.insert(
            tool_id,
            caps.tools.tools.get(&tool_id).unwrap().clone(),
        );
        let child_toolset = AgentToolset {
            tools: replacement,
        };

        let result = caps
            .derive_child_capabilities(&ToolInheritance::Replace(child_toolset));
        assert!(result.is_ok());
        let child_set = result.unwrap();
        assert!(child_set.tools.contains_key(&tool_id));
    }

    #[test]
    fn replace_with_non_delegatable_tool_is_rejected() {
        let (caps, _fs_read_id, shell_exec_id) = parent_with_mixed_tools();

        // Build a replacement toolset with the non-delegatable tool
        let mut replacement = HashMap::new();
        replacement.insert(
            shell_exec_id,
            caps.tools.tools.get(&shell_exec_id).unwrap().clone(),
        );
        let child_toolset = AgentToolset {
            tools: replacement,
        };

        let result = caps
            .derive_child_capabilities(&ToolInheritance::Replace(child_toolset));
        assert!(result.is_err());
        match result {
            Err(CapabilityError::NotDelegatable(id)) => assert_eq!(id, shell_exec_id),
            other => panic!("expected NotDelegatable, got {other:?}"),
        }
    }
}

//! Tool descriptor, capability, call, and result types for the harness protocol.
//!
//! This module defines the core tool abstractions: how tools are described,
//! how their usage is policed, how they are called, and how results are reported.

use std::collections::HashMap;

use serde::{Deserialize, Serialize};

use crate::ids::{ToolCallId, ToolId};

// ---------------------------------------------------------------------------
// Tool descriptor & policy
// ---------------------------------------------------------------------------

/// Describes a tool's identity, purpose, and expected input schema.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ToolDescriptor {
    /// Unique identifier for this tool.
    pub id: ToolId,
    /// Human-readable name of the tool.
    pub name: String,
    /// Description of what the tool does.
    pub description: String,
    /// JSON Schema describing the expected input arguments.
    pub input_schema: serde_json::Value,
}

/// Determines how a tool's invocation is authorised.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub enum PermissionMode {
    /// Automatically allowed.
    Allow,
    /// Requires user confirmation.
    Ask,
    /// Blocked.
    Deny,
}

/// Access policy for a single tool.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ToolPolicy {
    /// The permission level assigned to this tool.
    pub permission: PermissionMode,
    /// Whether the tool is currently enabled.
    pub enabled: bool,
}

/// A tool's full capability record, combining its descriptor with a policy.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ToolCapability {
    /// The tool's descriptor.
    pub descriptor: ToolDescriptor,
    /// The access policy for this tool.
    pub policy: ToolPolicy,
    /// Whether this tool can be delegated to sub-agents.
    pub delegatable: bool,
}

// ---------------------------------------------------------------------------
// Agent toolset
// ---------------------------------------------------------------------------

/// The collection of tools an agent has access to.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct AgentToolset {
    /// Map of tool ID to its capability record.
    pub tools: HashMap<ToolId, ToolCapability>,
}

impl AgentToolset {
    /// Returns descriptors for all currently enabled tools.
    ///
    /// This filters the internal map to only those [`ToolCapability`] entries
    /// whose [`ToolPolicy::enabled`] field is `true`.
    pub fn enabled_descriptors(&self) -> Vec<&ToolDescriptor> {
        self.tools
            .values()
            .filter(|tc| tc.policy.enabled)
            .map(|tc| &tc.descriptor)
            .collect()
    }
}

// ---------------------------------------------------------------------------
// Tool call & result types
// ---------------------------------------------------------------------------

/// Represents an invocation of a tool.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ToolCall {
    /// Unique identifier for this call.
    pub id: ToolCallId,
    /// The name of the tool being called.
    pub name: String,
    /// The arguments passed to the tool, as a JSON value.
    pub arguments: serde_json::Value,
}

/// The outcome of a tool call.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ToolResult {
    /// The ID of the call this result belongs to.
    pub call_id: ToolCallId,
    /// The output produced by the tool.
    pub output: serde_json::Value,
    /// Whether the tool execution resulted in an error.
    pub is_error: bool,
}

/// A lightweight summary of a tool result, suitable for logging or preview.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ToolResultSummary {
    /// Whether the tool execution resulted in an error.
    pub has_error: bool,
    /// A short textual preview of the output.
    pub output_preview: String,
}

/// Categorised errors that can occur during tool execution.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub enum ToolError {
    /// The tool reported a failure during execution.
    ExecutionFailed,
    /// The call was not authorised.
    PermissionDenied,
    /// The tool did not respond within the allowed time.
    Timeout,
    /// An internal system error occurred.
    Internal,
}

/// Progress update for a long-running tool invocation.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ToolProgress {
    /// A human-readable status message.
    pub status: String,
    /// Progress fraction between 0.0 and 1.0.
    pub fraction: f64,
}

// ---------------------------------------------------------------------------
// Tests
// ---------------------------------------------------------------------------

#[cfg(test)]
mod tests {
    use super::*;
    use crate::ids::ToolId;

    /// Verifies that `enabled_descriptors` returns only tools whose policy has
    /// `enabled: true`, skipping disabled ones.
    #[test]
    fn enabled_descriptors_filters_disabled_tools() {
        let id_a = ToolId::new();
        let id_b = ToolId::new();
        let id_c = ToolId::new();

        let mut tools = HashMap::new();

        // Enabled tool
        tools.insert(
            id_a,
            ToolCapability {
                descriptor: ToolDescriptor {
                    id: id_a,
                    name: "alpha".into(),
                    description: "First tool".into(),
                    input_schema: serde_json::json!({}),
                },
                policy: ToolPolicy {
                    permission: PermissionMode::Allow,
                    enabled: true,
                },
                delegatable: false,
            },
        );

        // Disabled tool
        tools.insert(
            id_b,
            ToolCapability {
                descriptor: ToolDescriptor {
                    id: id_b,
                    name: "beta".into(),
                    description: "Second tool".into(),
                    input_schema: serde_json::json!({}),
                },
                policy: ToolPolicy {
                    permission: PermissionMode::Deny,
                    enabled: false,
                },
                delegatable: false,
            },
        );

        // Another enabled tool
        tools.insert(
            id_c,
            ToolCapability {
                descriptor: ToolDescriptor {
                    id: id_c,
                    name: "gamma".into(),
                    description: "Third tool".into(),
                    input_schema: serde_json::json!({"type": "object"}),
                },
                policy: ToolPolicy {
                    permission: PermissionMode::Ask,
                    enabled: true,
                },
                delegatable: true,
            },
        );

        let set = AgentToolset { tools };
        let enabled = set.enabled_descriptors();

        assert_eq!(enabled.len(), 2, "expected exactly 2 enabled tools");
        assert!(
            enabled.iter().any(|d| d.name == "alpha"),
            "missing enabled tool alpha"
        );
        assert!(
            enabled.iter().any(|d| d.name == "gamma"),
            "missing enabled tool gamma"
        );
        assert!(
            enabled.iter().all(|d| d.name != "beta"),
            "disabled tool beta should not appear"
        );
    }

    /// Verifies that `enabled_descriptors` returns an empty vec when no tools
    /// are enabled.
    #[test]
    fn enabled_descriptors_empty_when_none_enabled() {
        let id = ToolId::new();
        let mut tools = HashMap::new();
        tools.insert(
            id,
            ToolCapability {
                descriptor: ToolDescriptor {
                    id,
                    name: "only_tool".into(),
                    description: "Only tool".into(),
                    input_schema: serde_json::json!({"type": "object"}),
                },
                policy: ToolPolicy {
                    permission: PermissionMode::Deny,
                    enabled: false,
                },
                delegatable: false,
            },
        );

        let set = AgentToolset { tools };
        let enabled = set.enabled_descriptors();
        assert!(enabled.is_empty(), "expected no enabled tools");
    }
}

//! Agent domain entity for the harness core.
//!
//! This module defines [`Agent`] — the primary domain entity that owns state,
//! capabilities, usage, and budget.  An agent can be a root agent (no parent)
//! or a child/sub-agent spawned by another agent.
//!
//! # Lifecycle
//!
//! Agents are created via [`Agent::new`] and driven by commands via
//! [`Agent::apply`] (defined in `crate::transitions`).  They do **not**
//! perform I/O directly — instead they produce [`AgentEffect`]s that the
//! runtime interprets.

use harness_protocol::backend::{BackendBinding, BackendCapabilities};
use harness_protocol::commands::AgentStatus;
use harness_protocol::ids::{AgentId, SessionId};
use harness_protocol::tools::AgentToolset;
use harness_protocol::usage::AgentBudget;

use crate::agent_state::AgentState;
use crate::capabilities::{AgentCapabilities, WorkspaceCapabilities};

// ---------------------------------------------------------------------------
// UsageLedger
// ---------------------------------------------------------------------------

/// A ledger of usage records for an agent.
///
/// This is a minimal placeholder that will be extended with aggregation
/// methods (self-usage, descendant-usage, tree-sum) in a follow-up task.
#[derive(Debug, Clone, Default)]
pub struct UsageLedger {
    /// The ordered list of usage records accumulated by this agent.
    pub records: Vec<harness_protocol::usage::UsageRecord>,
}

// ---------------------------------------------------------------------------
// Agent
// ---------------------------------------------------------------------------

/// An independent reasoning worker — the primary domain entity of the harness.
///
/// An agent owns:
/// - Identity (`id`, `session_id`, `parent_id`)
/// - State (`status`, transcript, pending tool calls, children, errors)
/// - Backend binding (which backend to use, how to reach it)
/// - Capabilities (what tools, operations, and permissions the agent has)
/// - Usage tracking (token counts, cost)
/// - Budget constraints (limits on tokens, cost, children)
///
/// Agents form a tree: a session has one root agent, and root agents may spawn
/// child agents.  Every agent (root or child) is a full `Agent` instance —
/// there is no separate `SubAgent` type.
#[derive(Debug, Clone)]
pub struct Agent {
    /// Unique identifier for this agent.
    pub id: AgentId,
    /// The session this agent belongs to.
    pub session_id: SessionId,
    /// The parent agent, if any (root agents have `None`).
    pub parent_id: Option<AgentId>,

    /// The agent's mutable state (status, transcript, pending tools, etc.).
    pub state: AgentState,

    /// The backend binding — a reference + descriptor identifying which
    /// execution backend this agent uses.
    pub backend: BackendBinding,

    /// The capabilities granted to this agent (tools, spawn permissions, etc.).
    pub capabilities: AgentCapabilities,

    /// The accumulated usage ledger for this agent (does **not** include
    /// descendant usage — that is aggregated separately).
    pub usage: UsageLedger,

    /// Budgetary limits for this agent.
    pub budget: AgentBudget,
}

impl Agent {
    /// Creates a new `Agent` with the given identity, backend, capabilities,
    /// and budget.
    ///
    /// The agent is initialised in the [`Idle`](AgentStatus::Idle) status with
    /// an empty transcript, no active run, no pending tools, no children, and
    /// an empty usage ledger.
    pub fn new(
        id: AgentId,
        session_id: SessionId,
        parent_id: Option<AgentId>,
        system_prompt: String,
        backend: BackendBinding,
        capabilities: AgentCapabilities,
        budget: AgentBudget,
    ) -> Self {
        Self {
            id,
            session_id,
            parent_id,
            state: AgentState {
                status: AgentStatus::Idle,
                current_operation: None,
                system_prompt,
                messages: Vec::new(),
                active_run: None,
                pending_tools: std::collections::HashMap::new(),
                children: Vec::new(),
                last_error: None,
            },
            backend,
            capabilities,
            usage: UsageLedger::default(),
            budget,
        }
    }

    /// Returns `true` if this agent is a root agent (has no parent).
    ///
    /// Root agents are created directly by a session.  Non-root agents are
    /// spawned by another agent as children.
    ///
    /// # Examples
    ///
    /// ```
    /// use harness_protocol::ids::AgentId;
    /// // A root agent has parent_id: None
    /// assert!(AgentId::new() != AgentId::new()); // just a demo
    /// ```
    pub fn is_root(&self) -> bool {
        self.parent_id.is_none()
    }
}

