    /// Creates a minimal `BackendBinding` for testing.
    fn test_backend() -> BackendBinding {
        BackendBinding {
            reference: BackendReference {
                integration: IntegrationId::new(),
                configuration: ConfigurationId::new(),
                model: None,
            },
            descriptor: BackendDescriptor {
                id: BackendId::new(),
                name: "test-backend".into(),
                description: "Test backend".into(),
                capabilities: BackendCapabilities {
                    tool_calls: true,
                    ..Default::default()
                },
            },
        }
    }

    /// Creates a root agent (parent_id: None) with test defaults.
    fn create_root_agent() -> Agent {
        Agent::new(
            AgentId::new(),
            SessionId::new(),
            None, // root
            "You are a helpful assistant.".to_string(),
            test_backend(),
            test_capabilities(),
            AgentBudget {
                max_total_tokens: Some(100_000),
                ..Default::default()
            },
        )
    }

    /// Creates a child agent (parent_id: Some) with test defaults.
    fn create_child_agent(parent_id: AgentId) -> Agent {
        Agent::new(
            AgentId::new(),
            SessionId::new(),
            Some(parent_id),
            "You are a helpful assistant (child).".to_string(),
            test_backend(),
            test_capabilities(),
            AgentBudget {
                max_total_tokens: Some(50_000),
                ..Default::default()
            },
        )
    }

    // -----------------------------------------------------------------------
    // Construction
    // -----------------------------------------------------------------------

    #[test]
    fn root_agent_construction() {
        let agent = create_root_agent();
        assert_eq!(agent.state.status, AgentStatus::Idle);
        assert!(agent.state.messages.is_empty());
        assert!(agent.state.pending_tools.is_empty());
        assert!(agent.state.active_run.is_none());
        assert!(agent.state.children.is_empty());
        assert!(agent.state.last_error.is_none());
        assert!(agent.state.current_operation.is_none());
        assert!(agent.usage.records.is_empty());
    }

    #[test]
    fn child_agent_construction() {
        let parent_id = AgentId::new();
        let agent = create_child_agent(parent_id);
        assert_eq!(agent.state.status, AgentStatus::Idle);
        assert_eq!(agent.parent_id, Some(parent_id));
        assert!(agent.state.messages.is_empty());
        assert!(agent.usage.records.is_empty());
    }

    // -----------------------------------------------------------------------
    // is_root
    // -----------------------------------------------------------------------

    #[test]
    fn root_agent_is_root() {
        let agent = create_root_agent();
        assert!(agent.is_root(), "root agent should report is_root() == true");
    }

    #[test]
    fn child_agent_is_not_root() {
        let parent_id = AgentId::new();
        let agent = create_child_agent(parent_id);
        assert!(!agent.is_root(), "child agent should report is_root() == false");
    }

    #[test]
    fn multiple_children_all_not_root() {
        let root = create_root_agent();
        assert!(root.is_root());

        let child1 = create_child_agent(root.id);
        assert!(!child1.is_root());

        let child2 = create_child_agent(root.id);
        assert!(!child2.is_root());

        // Grandchild: child of child1
        let grandchild = create_child_agent(child1.id);
        assert!(!grandchild.is_root());
    }
}

//! Integration tests for `harness_protocol::ids`.

use harness_protocol::ids::*;
use std::str::FromStr;
use uuid::Uuid;

// ---------------------------------------------------------------------------
// Round-trip serialization
// ---------------------------------------------------------------------------

/// Helper: serialize an ID to JSON, then deserialize it back and check equality.
fn roundtrip_json<T>(id: &T)
where
    T: serde::Serialize + serde::de::DeserializeOwned + PartialEq + std::fmt::Debug,
{
    let json = serde_json::to_string(id).expect("serialize");
    let deserialized: T = serde_json::from_str(&json).expect("deserialize");
    assert_eq!(*id, deserialized, "JSON round-trip failed");
}

/// Helper: serialize an ID via Display, then parse it back via FromStr and check equality.
fn roundtrip_display<T>(id: &T)
where
    T: ToString + FromStr + PartialEq + std::fmt::Debug,
    T::Err: std::fmt::Debug,
{
    let s = id.to_string();
    let parsed: T = T::from_str(&s).expect("parse from display string");
    assert_eq!(*id, parsed, "Display/FromStr round-trip failed");
}

/// Generates a round-trip test for a given ID type.
macro_rules! test_roundtrip {
    ($name:ident, $ty:ty) => {
        #[test]
        fn $name() {
            let id = <$ty>::new();
            roundtrip_json(&id);
            roundtrip_display(&id);
        }
    };
}

test_roundtrip!(session_id_roundtrip, SessionId);
test_roundtrip!(agent_id_roundtrip, AgentId);
test_roundtrip!(run_id_roundtrip, RunId);
test_roundtrip!(request_id_roundtrip, RequestId);
test_roundtrip!(tool_call_id_roundtrip, ToolCallId);
test_roundtrip!(message_id_roundtrip, MessageId);
test_roundtrip!(event_id_roundtrip, EventId);
test_roundtrip!(permission_id_roundtrip, PermissionId);
test_roundtrip!(tool_id_roundtrip, ToolId);
test_roundtrip!(integration_id_roundtrip, IntegrationId);
test_roundtrip!(configuration_id_roundtrip, ConfigurationId);
test_roundtrip!(model_id_roundtrip, ModelId);
test_roundtrip!(backend_id_roundtrip, BackendId);
