/// Check that 100 generated IDs of a type are all distinct.
macro_rules! test_uniqueness {
    ($name:ident, $ty:ty) => {
        #[test]
        fn $name() {
            const N: usize = 100;
            let mut ids = std::collections::HashSet::new();
            for _ in 0..N {
                let id = <$ty>::new();
                assert!(
                    ids.insert(id),
                    "duplicate {} generated",
                    stringify!($ty)
                );
            }
            assert_eq!(ids.len(), N, "expected {N} unique IDs");
        }
    };
}

