//! Usage ledger aggregation and tree-sum logic.
//!
//! This module extends [`UsageLedger`] with methods for aggregating usage
//! records and provides [`compute_agent_usage_summary`] for tree-sum
//! computation without double-counting.
//!
//! The **"unknown is not zero"** invariant is preserved throughout all
//! aggregation — if any operand is unknown (`None`) the result remains
//! unknown.

use harness_protocol::usage::{ModelUsage, UsageRecord, UsageValue};

use crate::agent::UsageLedger;

// ---------------------------------------------------------------------------
// AgentUsageSummary — tree‑sum breakdown
// ---------------------------------------------------------------------------

/// A three-level summary of an agent's token usage.
///
/// - [`self_usage`](AgentUsageSummary::self_usage): usage from this agent's
///   own records only (direct backend requests).
/// - [`descendant_usage`](AgentUsageSummary::descendant_usage): usage from
///   all descendant agents (children, grandchildren, …).
/// - [`inclusive_usage`](AgentUsageSummary::inclusive_usage):  the total
///   usage attributable to this agent (`self_usage + descendant_usage`).
#[derive(Debug, Clone)]
pub struct AgentUsageSummary {
    /// Usage from this agent's own records.
    pub self_usage: ModelUsage,
    /// Usage from all descendant agents (children, grandchildren, etc.).
    pub descendant_usage: ModelUsage,
    /// Total usage = self + descendant (no double counting).
    pub inclusive_usage: ModelUsage,
}

// ---------------------------------------------------------------------------
// UsageLedger methods
// ---------------------------------------------------------------------------

impl UsageLedger {
    /// Creates a new empty usage ledger.
    pub fn new() -> Self {
        UsageLedger {
            records: Vec::new(),
        }
    }

    /// Adds a single usage record to the ledger.
    pub fn add_record(&mut self, record: UsageRecord) {
        self.records.push(record);
    }

    /// Aggregates all records in this ledger into a single [`ModelUsage`].
    ///
    /// This only includes this agent's **own** records — descendant usage
    /// is computed separately via [`compute_agent_usage_summary`].
    pub fn self_usage(&self) -> ModelUsage {
        self.aggregate(&self.records)
    }

    /// Internal helper: sums a slice of records field-by-field using
    /// [`UsageValue::checked_add`] so the "unknown is not zero" invariant
    /// is preserved.
    fn aggregate(&self, records: &[UsageRecord]) -> ModelUsage {
        // Start from an all-unknown baseline.
        let mut result = ModelUsage {
            input_tokens: UsageValue::new(None),
            output_tokens: UsageValue::new(None),
            cache_read_tokens: UsageValue::new(None),
            cache_write_tokens: UsageValue::new(None),
            reasoning_tokens: UsageValue::new(None),
            total_tokens: UsageValue::new(None),
        };

        for record in records {
            result = ModelUsage {
                input_tokens: result
                    .input_tokens
                    .checked_add(record.model_usage.input_tokens),
                output_tokens: result
                    .output_tokens
                    .checked_add(record.model_usage.output_tokens),
                cache_read_tokens: result
                    .cache_read_tokens
                    .checked_add(record.model_usage.cache_read_tokens),
                cache_write_tokens: result
                    .cache_write_tokens
                    .checked_add(record.model_usage.cache_write_tokens),
                reasoning_tokens: result
                    .reasoning_tokens
                    .checked_add(record.model_usage.reasoning_tokens),
                total_tokens: result
                    .total_tokens
                    .checked_add(record.model_usage.total_tokens),
            };
        }

        result
    }
}

// ---------------------------------------------------------------------------
// Tree‑sum aggregation
// ---------------------------------------------------------------------------

/// Computes a tree-sum usage summary for an agent.
///
/// Given this agent's own records and the summaries of all direct children,
/// this function computes:
///
/// - **`self_usage`** — aggregated from `self_records`.
/// - **`descendant_usage`** — sum of every child's `inclusive_usage`.
/// - **`inclusive_usage`** — `self_usage + descendant_usage` (no double
///   counting, because each child's `inclusive_usage` already includes
///   *its* descendants).
///
/// The "unknown is not zero" invariant is preserved throughout — if any
/// field is unknown in any record or child summary, the corresponding
/// aggregate field remains unknown.
pub fn compute_agent_usage_summary(
    self_records: &[UsageRecord],
    child_summaries: &[AgentUsageSummary],
) -> AgentUsageSummary {
    // 1. Self-usage: aggregate this agent's own records.
    let self_usage = UsageLedger {
        records: self_records.to_vec(),
    }
    .self_usage();

    // 2. Descendant usage: sum every child's inclusive_usage.
    let mut descendant_usage = ModelUsage {
        input_tokens: UsageValue::new(None),
        output_tokens: UsageValue::new(None),
        cache_read_tokens: UsageValue::new(None),
        cache_write_tokens: UsageValue::new(None),
        reasoning_tokens: UsageValue::new(None),
        total_tokens: UsageValue::new(None),
    };

    for child in child_summaries {
        descendant_usage = ModelUsage {
            input_tokens: descendant_usage
                .input_tokens
                .checked_add(child.inclusive_usage.input_tokens),
            output_tokens: descendant_usage
                .output_tokens
                .checked_add(child.inclusive_usage.output_tokens),
            cache_read_tokens: descendant_usage
                .cache_read_tokens
                .checked_add(child.inclusive_usage.cache_read_tokens),
            cache_write_tokens: descendant_usage
                .cache_write_tokens
                .checked_add(child.inclusive_usage.cache_write_tokens),
            reasoning_tokens: descendant_usage
                .reasoning_tokens
                .checked_add(child.inclusive_usage.reasoning_tokens),
            total_tokens: descendant_usage
                .total_tokens
                .checked_add(child.inclusive_usage.total_tokens),
        };
    }

    // 3. Inclusive usage: self + descendant.
    let inclusive_usage = ModelUsage {
        input_tokens: self_usage
            .input_tokens
            .checked_add(descendant_usage.input_tokens),
        output_tokens: self_usage
            .output_tokens
            .checked_add(descendant_usage.output_tokens),
        cache_read_tokens: self_usage
            .cache_read_tokens
            .checked_add(descendant_usage.cache_read_tokens),
        cache_write_tokens: self_usage
            .cache_write_tokens
            .checked_add(descendant_usage.cache_write_tokens),
        reasoning_tokens: self_usage
            .reasoning_tokens
            .checked_add(descendant_usage.reasoning_tokens),
        total_tokens: self_usage
            .total_tokens
            .checked_add(descendant_usage.total_tokens),
    };

    AgentUsageSummary {
        self_usage,
        descendant_usage,
        inclusive_usage,
    }
}

// ---------------------------------------------------------------------------
// Tests
// ---------------------------------------------------------------------------

#[cfg(test)]
mod tests {
    use harness_protocol::usage::{Cost, ModelUsage, UsageRecord, UsageValue};

    use super::*;

    // -----------------------------------------------------------------------
    // Helpers
    // -----------------------------------------------------------------------

    /// Creates a minimal `UsageRecord` with the given `input_tokens` value
    /// and all other fields set to unknown.
    fn record_with_input(input_tokens: u64) -> UsageRecord {
        UsageRecord {
            model_usage: ModelUsage {
                input_tokens: UsageValue::new(Some(input_tokens)),
                output_tokens: UsageValue::new(None),
                cache_read_tokens: UsageValue::new(None),
                cache_write_tokens: UsageValue::new(None),
                reasoning_tokens: UsageValue::new(None),
                total_tokens: UsageValue::new(None),
            },
            cost: Cost {
                amount_usd: None,
                source: None,
            },
            tool_usage: None,
        }
    }

    /// Creates a fully-unknown `ModelUsage` baseline.
    fn unknown_usage() -> ModelUsage {
        ModelUsage {
            input_tokens: UsageValue::new(None),
            output_tokens: UsageValue::new(None),
            cache_read_tokens: UsageValue::new(None),
            cache_write_tokens: UsageValue::new(None),
            reasoning_tokens: UsageValue::new(None),
            total_tokens: UsageValue::new(None),
        }
    }

    // -----------------------------------------------------------------------
    // UsageLedger basics
    // -----------------------------------------------------------------------

    #[test]
    fn empty_ledger_self_usage_is_all_unknown() {
        let ledger = UsageLedger::new();
        let usage = ledger.self_usage();

        assert!(usage.input_tokens.is_unknown());
        assert!(usage.output_tokens.is_unknown());
        assert!(usage.cache_read_tokens.is_unknown());
        assert!(usage.cache_write_tokens.is_unknown());
        assert!(usage.reasoning_tokens.is_unknown());
        assert!(usage.total_tokens.is_unknown());
    }

    #[test]
    fn ledger_with_one_record() {
        let mut ledger = UsageLedger::new();
        ledger.add_record(record_with_input(42));
        let usage = ledger.self_usage();

        assert_eq!(usage.input_tokens.value(), Some(42));
        // All other fields remain unknown because records only set input_tokens
        assert!(usage.output_tokens.is_unknown());
    }

    #[test]
    fn ledger_with_multiple_records_sums_input_tokens() {
        let mut ledger = UsageLedger::new();
        ledger.add_record(record_with_input(10));
        ledger.add_record(record_with_input(20));
        ledger.add_record(record_with_input(30));

        let usage = ledger.self_usage();
        assert_eq!(usage.input_tokens.value(), Some(60));
    }

    // -----------------------------------------------------------------------
    // Tree-sum without double-counting
    // -----------------------------------------------------------------------

    #[test]
    fn tree_sum_no_double_counting() {
        // --- Parent: 2 self records ---
        let mut parent_ledger = UsageLedger::new();
        parent_ledger.add_record(record_with_input(1));
        parent_ledger.add_record(record_with_input(1));

        // --- Child: 1 self record ---
        let mut child_ledger = UsageLedger::new();
        child_ledger.add_record(record_with_input(1));

        // Build child summary (leaf: no descendants)
        let child_summary = AgentUsageSummary {
            self_usage: child_ledger.self_usage(),
            descendant_usage: unknown_usage(),
            inclusive_usage: child_ledger.self_usage(), // leaf: self == inclusive
        };

        // Build parent summary via tree-sum
        let summary = compute_agent_usage_summary(&parent_ledger.records, &[child_summary]);

        // self_usage = parent's own 2 records
        assert_eq!(
            summary.self_usage.input_tokens.value(),
            Some(2),
            "parent self_usage should sum its own 2 records"
        );

        // descendant_usage = child's inclusive_usage (child has 1 record)
        assert_eq!(
            summary.descendant_usage.input_tokens.value(),
            Some(1),
            "descendant_usage should sum child inclusive_usage"
        );

        // inclusive_usage = self (2) + descendant (1) = 3
        assert_eq!(
            summary.inclusive_usage.input_tokens.value(),
            Some(3),
            "inclusive_usage should be self + descendant without double counting"
        );
    }

    // -----------------------------------------------------------------------
    // Unknown fields remain unknown through aggregation
    // -----------------------------------------------------------------------

    #[test]
    fn unknown_fields_remain_unknown_after_tree_sum() {
        let mut parent_ledger = UsageLedger::new();
        // Both records only set input_tokens; output_tokens and others stay unknown
        parent_ledger.add_record(record_with_input(5));
        parent_ledger.add_record(record_with_input(5));

        let mut child_ledger = UsageLedger::new();
        child_ledger.add_record(record_with_input(3));

        let child_summary = AgentUsageSummary {
            self_usage: child_ledger.self_usage(),
            descendant_usage: unknown_usage(),
            inclusive_usage: child_ledger.self_usage(),
        };

        let summary = compute_agent_usage_summary(&parent_ledger.records, &[child_summary]);

        // input_tokens is known (sum of all records)
        assert_eq!(summary.inclusive_usage.input_tokens.value(), Some(13));

        // output_tokens was never set → must remain unknown
        assert!(summary.self_usage.output_tokens.is_unknown());
        assert!(summary.descendant_usage.output_tokens.is_unknown());
        assert!(summary.inclusive_usage.output_tokens.is_unknown());

        // Similarly for cache_read, cache_write, reasoning, total
        assert!(summary.inclusive_usage.cache_read_tokens.is_unknown());
        assert!(summary.inclusive_usage.cache_write_tokens.is_unknown());
        assert!(summary.inclusive_usage.reasoning_tokens.is_unknown());
        assert!(summary.inclusive_usage.total_tokens.is_unknown());
    }

    // -----------------------------------------------------------------------
    // Partial unknown: one record has data, another doesn't
    // -----------------------------------------------------------------------

    #[test]
    fn partial_unknown_poisons_aggregate() {
        let mut ledger = UsageLedger::new();

        // First record: output_tokens is known (10)
        ledger.add_record(UsageRecord {
            model_usage: ModelUsage {
                input_tokens: UsageValue::new(Some(5)),
                output_tokens: UsageValue::new(Some(10)),
                cache_read_tokens: UsageValue::new(None),
                cache_write_tokens: UsageValue::new(None),
                reasoning_tokens: UsageValue::new(None),
                total_tokens: UsageValue::new(None),
            },
            cost: Cost {
                amount_usd: None,
                source: None,
            },
            tool_usage: None,
        });

        // Second record: output_tokens is unknown
        ledger.add_record(UsageRecord {
            model_usage: ModelUsage {
                input_tokens: UsageValue::new(Some(3)),
                output_tokens: UsageValue::new(None), // unknown
                cache_read_tokens: UsageValue::new(None),
                cache_write_tokens: UsageValue::new(None),
                reasoning_tokens: UsageValue::new(None),
                total_tokens: UsageValue::new(None),
            },
            cost: Cost {
                amount_usd: None,
                source: None,
            },
            tool_usage: None,
        });

        let usage = ledger.self_usage();

        // input_tokens: both known → sum
        assert_eq!(usage.input_tokens.value(), Some(8));

        // output_tokens: known + unknown → unknown (poisoned)
        assert!(usage.output_tokens.is_unknown());
    }
}

//! Budget enforcement for agent execution.
//!
//! This module provides [`BudgetError`] and extends [`AgentBudget`] with
//! runtime check methods that enforce token usage and cost limits before
//! a backend request or tool execution is allowed to proceed.

use harness_protocol::usage::{AgentBudget, Cost, ModelUsage};

// ---------------------------------------------------------------------------
// BudgetError
// ---------------------------------------------------------------------------

/// Errors that can occur when checking an agent's budget.
#[derive(Debug, Clone, thiserror::Error)]
pub enum BudgetError {
    /// A usage limit was exceeded (e.g. total tokens).
    #[error("Usage exceeds budget: {0}")]
    Exceeded(String),

    /// The monetary cost limit was exceeded.
    #[error("Cost exceeds budget")]
    CostExceeded,
}

// ---------------------------------------------------------------------------
// AgentBudget check methods
// ---------------------------------------------------------------------------

impl AgentBudget {
    /// Checks whether the given [`ModelUsage`] exceeds the budget's
    /// `max_total_tokens` limit.
    ///
    /// Returns `Ok(())` if the usage is within limits or if no limit is set
    /// (`max_total_tokens` is `None`).  Returns
    /// [`BudgetError::Exceeded`] if the usage exceeds the limit.
    ///
    /// If the usage's `total_tokens` is unknown (`None`), the check is
    /// skipped — we cannot reject what we cannot measure.
    pub fn check_usage(&self, usage: &ModelUsage) -> Result<(), BudgetError> {
        if let (Some(max), Some(current)) = (self.max_total_tokens, usage.total_tokens.value()) {
            if current > max {
                return Err(BudgetError::Exceeded(format!(
                    "total tokens {} exceeds limit {}",
                    current, max
                )));
            }
        }
        Ok(())
    }

    /// Checks whether the given [`Cost`] exceeds the budget's `max_cost_usd`
    /// limit.
    ///
    /// Returns `Ok(())` if the cost is within limits or if no limit is set
    /// (`max_cost_usd` is `None`).  Returns
    /// [`BudgetError::CostExceeded`] if the cost exceeds the limit.
    ///
    /// If the cost's `amount_usd` is unknown (`None`), the check is skipped.
    pub fn check_cost(&self, cost: &Cost) -> Result<(), BudgetError> {
        if let (Some(max), Some(actual)) = (self.max_cost_usd, cost.amount_usd) {
            if actual > max {
                return Err(BudgetError::CostExceeded);
            }
        }
        Ok(())
    }
}

