            reasoning_tokens: UsageValue::new(None),
            total_tokens: UsageValue::new(total),
        },
        cost: Cost {
            amount_usd: None,
            source: None,
        },
        finish_reason: "end_turn".into(),
    }
}

// ===========================================================================
// tool_call_emits_execute_effect
// ===========================================================================

#[test]
fn tool_call_emits_execute_effect() {
    let mut agent = create_test_agent();

    // Step 1: Start a run
    let effects = agent.apply(AgentCommand::StartRun {
        input: UserInput {
            text: "Run a tool".into(),
            attachments: vec![],
        },
    });

    assert_eq!(agent.state.status, AgentStatus::PreparingContext);
    let run_id = agent.state.active_run.expect("run_id must be set");

    // Step 2: Receive a tool call request from the backend
    let call_id = ToolCallId::new();
    let _effects2 = agent.apply(AgentCommand::BackendEvent {
        run_id,
        event: ExecutionEvent::ToolCallRequested {
            request_id: RequestId::new(),
            call: ToolCall {
                id: call_id,
                name: "test-tool".into(),
                arguments: serde_json::json!({"key": "value"}),
            },
        },
    });

    assert!(
        agent.state.pending_tools.contains_key(&call_id),
        "tool call should be pending"
    );

    // Step 3: Complete the tool — this should emit an ExecuteBackend effect
    // because pending tools become empty and active_run is set.
    let effects3 = agent.apply(AgentCommand::ToolCompleted {
        call_id,
        result: ToolResult {
            call_id,
            output: serde_json::json!({"result": "ok"}),
            is_error: false,
        },
    });

    // The tool call should be removed from pending
    assert!(
        !agent.state.pending_tools.contains_key(&call_id),
        "tool call should be removed from pending"
    );

    // A ToolCallCompleted event must be emitted
    let has_tool_completed = effects3.iter().any(|e| {
        matches!(e, AgentEffect::Emit { event: AgentEvent::ToolCallCompleted { .. } })
    });
    assert!(has_tool_completed, "expected ToolCallCompleted event");

    // Because pending tools is now empty and active_run is set, an
    // ExecuteBackend effect must be emitted to continue the run.
    let has_execute_backend = effects3
        .iter()
        .any(|e| matches!(e, AgentEffect::ExecuteBackend { .. }));
    assert!(
        has_execute_backend,
        "expected ExecuteBackend effect after tool completion"
    );

    // Status should transition to WaitingForBackend
    assert_eq!(agent.state.status, AgentStatus::WaitingForBackend);
}

// ===========================================================================
// cancel_stops_further_effects
// ===========================================================================

#[test]
fn cancel_stops_further_effects() {
    let mut agent = create_test_agent();

    // Start a run
    let _effects = agent.apply(AgentCommand::StartRun {
        input: UserInput {
            text: "Do something".into(),
            attachments: vec![],
        },
    });
    assert_eq!(agent.state.status, AgentStatus::PreparingContext);
    assert!(agent.state.active_run.is_some());

    // Cancel
    let cancel_effects = agent.apply(AgentCommand::Cancel);

    // State must be Cancelled, active_run cleared
    assert_eq!(agent.state.status, AgentStatus::Cancelled);
    assert!(
        agent.state.active_run.is_none(),
        "active_run should be cleared on cancel"
    );

    // Effects must include a StateChanged to Cancelled and a Completed event
    let has_state_changed = cancel_effects.iter().any(|e| {
        matches!(
            e,
            AgentEffect::Emit {
                event: AgentEvent::StateChanged {
                    from: _,
                    to: AgentStatus::Cancelled,
                },
            }
        )
    });
    assert!(
        has_state_changed,
        "expected StateChanged to Cancelled"
    );

    let has_completed = cancel_effects.iter().any(|e| {
        matches!(
            e,
            AgentEffect::Emit {
                event: AgentEvent::Completed {
                    outcome: AgentOutcome::Cancelled,
                },
            }
        )
    });
    assert!(
        has_completed,
        "expected Completed(Cancelled) event"
    );

    // After cancel, applying a Pause should leave status as Cancelled
    // (Pause only sets status to Paused unconditionally)
    // Actually Pause just sets status to Paused regardless of current
    // status — so this would change Cancelled to Paused, which is
    // intentional per the spec's simple pause semantics.
    // Instead, verify that Cancel is idempotent: re-cancelling still
    // produces the same effects.
    let recancel_effects = agent.apply(AgentCommand::Cancel);

    assert_eq!(
        agent.state.status,
        AgentStatus::Cancelled,
        "re-cancelling keeps Cancelled"
    );
    assert!(
        agent.state.active_run.is_none(),
        "active_run stays None after re-cancel"
    );

    // Re-cancelling still emits effects
    let has_recancel_completed = recancel_effects.iter().any(|e| {
        matches!(
            e,
            AgentEffect::Emit {
                event: AgentEvent::Completed {
                    outcome: AgentOutcome::Cancelled,
                },
            }
        )
    });
    assert!(
        has_recancel_completed,
        "re-cancel emits Completed(Cancelled)"
    );

    // Key invariant: no active run remains after cancellation
    assert!(agent.state.active_run.is_none());
}

// ===========================================================================
// permission_ask_blocks_until_resolved
// ===========================================================================

#[test]
fn permission_ask_blocks_until_resolved() {
    let mut agent = create_test_agent();

    // Simulate that the agent is waiting for a permission decision
    agent.state.status = AgentStatus::WaitingForPermission;
    let run_id = RunId::new();
    agent.state.active_run = Some(run_id);

    // Resolve with Approved — status should transition to Executing
    let approved_effects = agent.apply(AgentCommand::PermissionResolved {
        id: PermissionId::new(),
        decision: PermissionDecision::Approved,
    });

    assert_eq!(
        agent.state.status,
        AgentStatus::Executing,
        "approved permission should transition to Executing"
    );

    let has_state_change = approved_effects.iter().any(|e| {
        matches!(
            e,
            AgentEffect::Emit {
                event: AgentEvent::StateChanged {
                    from: AgentStatus::WaitingForPermission,
                    to: AgentStatus::Executing,
                },
            }
        )
    });
    assert!(
        has_state_change,
        "expected StateChanged(WaitingForPermission -> Executing)"
    );

    // Now test Denied: reset to WaitingForPermission with an active run
    agent.state.status = AgentStatus::WaitingForPermission;
    agent.state.active_run = Some(run_id);

    let denied_effects = agent.apply(AgentCommand::PermissionResolved {
        id: PermissionId::new(),
        decision: PermissionDecision::Denied,
    });

    // On denial, status transitions to PreparingContext so the agent
    // can continue the run without the denied tool
    assert_eq!(
        agent.state.status,
        AgentStatus::PreparingContext,
        "denied permission should transition to PreparingContext"
    );

    // Denial should emit a StateChanged and an ExecuteBackend to continue
    let has_deny_state_change = denied_effects.iter().any(|e| {
        matches!(
            e,
            AgentEffect::Emit {
                event: AgentEvent::StateChanged {
                    from: AgentStatus::WaitingForPermission,
                    to: AgentStatus::PreparingContext,
                },
            }
        )
    });
    assert!(
        has_deny_state_change,
        "expected StateChanged(WaitingForPermission -> PreparingContext)"
    );

    let has_execute = denied_effects
        .iter()
        .any(|e| matches!(e, AgentEffect::ExecuteBackend { .. }));
    assert!(
        has_execute,
        "expected ExecuteBackend after denial to continue run"
    );
}

// ===========================================================================
// child_failure_does_not_crash_parent_state
// ===========================================================================

#[test]
fn child_failure_does_not_crash_parent_state() {
    let mut agent = create_test_agent();
    let child_id = AgentId::new();

    // Add the child to the parent's children list
    agent.state.children.push(child_id);

    // Simulate child failure
    let effects = agent.apply(AgentCommand::ChildFailed {
        agent_id: child_id,
        error: AgentError {
            message: "Child encountered an error".into(),
            code: "CHILD_FAILED".into(),
            details: Some(serde_json::json!({"reason": "timeout"})),
        },
    });

    // The parent's children list should no longer contain the failed child
    assert!(
        !agent.state.children.contains(&child_id),
        "failed child should be removed from parent children list"
    );

    // The parent's last_error should be set to the child's error
    assert!(
        agent.state.last_error.is_some(),
        "parent last_error should be set on child failure"
    );
    if let Some(ref err) = agent.state.last_error {
        assert_eq!(err.message, "Child encountered an error");
        assert_eq!(err.code, "CHILD_FAILED");
    }

    // The parent must remain in its current status (Idle here) —
    // child failure must not crash the parent
    assert_eq!(
        agent.state.status,
        AgentStatus::Idle,
        "parent status must remain unchanged after child failure"
    );

    // Correct event must be emitted
    let has_event = effects.iter().any(|e| {
        matches!(
            e,
            AgentEffect::Emit {
                event: AgentEvent::ChildAgentCompleted {
                    agent_id,
                    outcome: AgentOutcome::Failed,
                },
            } if *agent_id == child_id
        )
    });
    assert!(has_event, "expected ChildAgentCompleted(Failed) event");

    // Additional invariant: parent's transcript and active_run are untouched
    assert!(
        agent.state.messages.is_empty(),
        "parent transcript untouched"
    );
    assert!(
        agent.state.active_run.is_none(),
        "parent active_run untouched"
    );
    assert!(
        agent.state.pending_tools.is_empty(),
        "parent pending_tools untouched"
    );
}

// ===========================================================================
// non_delegatable_tool_rejected_for_child (capability error)
// ===========================================================================

#[test]
fn non_delegatable_tool_rejected_for_child() {
    // Build a parent capabilities set with two tools:
    //   - fs.read    (delegatable, enabled)
    //   - shell.exec (NOT delegatable, enabled)
    let fs_read_id = ToolId::new();
    let shell_exec_id = ToolId::new();

    let mut tools = HashMap::new();

    tools.insert(
        fs_read_id,
        ToolCapability {
            descriptor: ToolDescriptor {
                id: fs_read_id,
                name: "fs.read".into(),
                description: "Read files".into(),
                input_schema: serde_json::json!({}),
            },
            policy: ToolPolicy {
                permission: PermissionMode::Allow,
                enabled: true,
            },
            delegatable: true,
        },
    );

    tools.insert(
        shell_exec_id,
        ToolCapability {
            descriptor: ToolDescriptor {
                id: shell_exec_id,
                name: "shell.exec".into(),
                description: "Execute shell commands".into(),
                input_schema: serde_json::json!({}),
            },
            policy: ToolPolicy {
                permission: PermissionMode::Allow,
                enabled: true,
            },
            delegatable: false,
        },
    );

    let caps = AgentCapabilities {
        tools: AgentToolset { tools },
        can_spawn_agents: true,
        max_child_depth: Some(5),
        workspace: WorkspaceCapabilities {
            can_read: true,
            can_write: false,
            can_search: false,
        },
        backend: BackendCapabilities {
            tool_calls: true,
            ..Default::default()
        },
    };

    // 1. Requesting ONLY the delegatable tool should succeed
    let result = caps.derive_child_capabilities(&ToolInheritance::Subset(vec![
        fs_read_id,
    ]));
    assert!(
        result.is_ok(),
        "delegatable tool subset should be accepted"
    );

    // 2. Requesting the non-delegatable tool MUST be rejected
    let result = caps.derive_child_capabilities(&ToolInheritance::Subset(vec![
        shell_exec_id,
    ]));
    assert!(result.is_err(), "non-delegatable tool must be rejected");
    match result {
        Err(CapabilityError::NotDelegatable(id)) => {
            assert_eq!(id, shell_exec_id, "error must reference shell.exec");
        }
        other => panic!(
            "expected CapabilityError::NotDelegatable, got {other:?}"
        ),
    }

    // 3. Requesting a non-existent tool must also be rejected
    let unknown_id = ToolId::new();
    let result = caps.derive_child_capabilities(&ToolInheritance::Subset(vec![
        unknown_id,
    ]));
    assert!(result.is_err(), "non-existent tool must be rejected");
    match result {
        Err(CapabilityError::ToolNotFound(id)) => {
            assert_eq!(id, unknown_id, "error must reference unknown tool");
        }
        other => panic!(
            "expected CapabilityError::ToolNotFound, got {other:?}"
        ),
    }

    // 4. Replace with a non-delegatable tool must also be rejected
    let mut replacement = HashMap::new();
    replacement.insert(
        shell_exec_id,
        ToolCapability {
            descriptor: ToolDescriptor {
                id: shell_exec_id,
                name: "shell.exec".into(),
                description: "Execute shell commands".into(),
                input_schema: serde_json::json!({}),
            },
            policy: ToolPolicy {
                permission: PermissionMode::Allow,
                enabled: true,
            },
            delegatable: false,
        },
    );
    let child_toolset = AgentToolset {
        tools: replacement,
    };
    let result = caps.derive_child_capabilities(&ToolInheritance::Replace(
        child_toolset,
    ));
    assert!(
        result.is_err(),
        "Replace with non-delegatable must be rejected"
    );
    match result {
        Err(CapabilityError::NotDelegatable(id)) => {
            assert_eq!(id, shell_exec_id);
        }
        other => panic!(
            "expected CapabilityError::NotDelegatable, got {other:?}"
        ),
    }
}

// ===========================================================================
// unknown_usage_stays_none_through_a_full_run (invariant)
// ===========================================================================

#[test]
fn unknown_usage_stays_none_through_a_full_run() {
    let mut agent = create_test_agent();

    // Step 1: StartRun
    let _effects = agent.apply(AgentCommand::StartRun {
        input: UserInput {
            text: "Do something".into(),
            attachments: vec![],
        },
    });
    let run_id = agent.state.active_run.expect("run_id must be set");

    // Step 2: Receive a UsageUpdate with ALL fields unknown (None)
    let _effects = agent.apply(AgentCommand::BackendEvent {
        run_id,
        event: ExecutionEvent::UsageUpdate {
            request_id: RequestId::new(),
            usage: ModelUsage {
                input_tokens: UsageValue::new(None),
                output_tokens: UsageValue::new(None),
                cache_read_tokens: UsageValue::new(None),
                cache_write_tokens: UsageValue::new(None),
                reasoning_tokens: UsageValue::new(None),
                total_tokens: UsageValue::new(None),
            },
        },
    });

    // Step 3: Complete the run with usage having SOME fields unknown
    let _effects = agent.apply(AgentCommand::BackendEvent {
        run_id,
        event: ExecutionEvent::Completed {
            request_id: RequestId::new(),
            result: make_result(Some(10), None, Some(35)),
        },
    });

    // After completion, inspect the usage ledger
    let records = &agent.usage.records;

    // We should have 2 records (UsageUpdate + Completed)
    assert_eq!(records.len(), 2, "expected 2 usage records");

    // First record: all unknown
    assert!(
        records[0].model_usage.input_tokens.is_unknown(),
        "first record input_tokens must be unknown"
    );
    assert!(
        records[0].model_usage.output_tokens.is_unknown(),
        "first record output_tokens must be unknown"
    );
    assert!(
        records[0].model_usage.total_tokens.is_unknown(),
        "first record total_tokens must be unknown"
    );

    // Second record: input_tokens known (10), output_tokens unknown,
    // total_tokens known (35)
    assert_eq!(
        records[1].model_usage.input_tokens.value(),
        Some(10),
        "second record input_tokens should be Some(10)"
    );
    assert!(
        records[1].model_usage.output_tokens.is_unknown(),
        "second record output_tokens must stay unknown"
    );
    assert_eq!(
        records[1].model_usage.total_tokens.value(),
        Some(35),
        "second record total_tokens should be Some(35)"
    );

    // Critical invariant: if we aggregate, the output_tokens should remain
    // unknown because both records had it unknown — checked_add(None, None)
    // = None.
    let aggregated_output = records
        .iter()
        .fold(UsageValue::new(None), |acc, r| {
            acc.checked_add(r.model_usage.output_tokens)
        });
    assert!(
        aggregated_output.is_unknown(),
        "aggregated output_tokens must remain unknown through full run"
    );

    // Final state must be Idle
    assert_eq!(agent.state.status, AgentStatus::Idle);
}

// ===========================================================================
// scripted_vertical_slice: full scripted sequence with exact state + effects
// assertions
// ===========================================================================

#[test]
fn scripted_vertical_slice() {
    let mut agent = create_test_agent();
    let tool_call_id = ToolCallId::new();

    // ------------------------------------------------------------------
    // Step 1: StartRun
    // ------------------------------------------------------------------
    let effects_1 = agent.apply(AgentCommand::StartRun {
        input: UserInput {
            text: "Help me with something".into(),
            attachments: vec![],
        },
    });

    // State assertions after StartRun
    assert_eq!(
        agent.state.status,
        AgentStatus::PreparingContext,
        "after StartRun: status should be PreparingContext"
    );
    let run_id = agent
        .state
        .active_run
        .expect("run_id must be set after StartRun");
    assert!(
        agent.state.pending_tools.is_empty(),
        "no pending tools after StartRun"
    );
    assert!(
        agent.state.messages.is_empty(),
        "transcript empty after StartRun"
    );

    // Effect assertions after StartRun
    assert_eq!(effects_1.len(), 3, "StartRun should produce exactly 3 effects");

    let has_state_changed = effects_1.iter().any(|e| {
        matches!(
            e,
            AgentEffect::Emit {
                event: AgentEvent::StateChanged {
                    from: AgentStatus::Idle,
                    to: AgentStatus::PreparingContext,
                },
            }
        )
    });
    assert!(
        has_state_changed,
        "effect[0]: StateChanged(Idle -> PreparingContext)"
    );

    let has_execute_backend = effects_1
        .iter()
        .any(|e| matches!(e, AgentEffect::ExecuteBackend { .. }));
    assert!(has_execute_backend, "effect[1]: ExecuteBackend");

    let has_run_started = effects_1.iter().any(|e| {
        matches!(
            e,
            AgentEffect::Emit {
                event: AgentEvent::RunStarted { .. },
            }
        )
    });
    assert!(has_run_started, "effect[2]: RunStarted");

    // ------------------------------------------------------------------
    // Step 2: BackendEvent(ToolCallRequested)
    // ------------------------------------------------------------------
    let effects_2 = agent.apply(AgentCommand::BackendEvent {
        run_id,
        event: ExecutionEvent::ToolCallRequested {
            request_id: RequestId::new(),
            call: ToolCall {
                id: tool_call_id,
                name: "test-tool".into(),
                arguments: serde_json::json!({"input": "test"}),
            },
        },
    });

    // State assertions
    assert!(
        agent.state.pending_tools.contains_key(&tool_call_id),
        "tool_call should be pending"
    );
    assert_eq!(
        agent.state.pending_tools.len(),
        1,
        "exactly one pending tool"
    );
    assert_eq!(
        agent.state.status,
        AgentStatus::PreparingContext,
        "status unchanged by ToolCallRequested"
    );

    // Effect assertions: exactly 1 effect (ToolCallRequested event)
    assert_eq!(
        effects_2.len(),
        1,
        "ToolCallRequested should produce exactly 1 effect"
    );

    let has_tool_requested = effects_2.iter().any(|e| {
        matches!(
            e,
            AgentEffect::Emit {
                event: AgentEvent::ToolCallRequested { .. },
            }
        )
    });
    assert!(has_tool_requested, "effect: ToolCallRequested");

    // ------------------------------------------------------------------
    // Step 3: ToolCompleted
    // ------------------------------------------------------------------
    let effects_3 = agent.apply(AgentCommand::ToolCompleted {
        call_id: tool_call_id,
        result: ToolResult {
            call_id: tool_call_id,
            output: serde_json::json!({"result": "ok"}),
            is_error: false,
        },
    });

    // State assertions
    assert!(
        !agent.state.pending_tools.contains_key(&tool_call_id),
        "tool call removed from pending"
    );
    assert!(
        agent.state.pending_tools.is_empty(),
        "no pending tools remain"
    );
    assert_eq!(
        agent.state.messages.len(),
        1,
        "one tool result message appended to transcript"
    );
    assert_eq!(
        agent.state.messages[0].role,
        harness_protocol::messages::MessageRole::Tool,
        "appended message must have Tool role"
    );
    assert_eq!(
        agent.state.status,
        AgentStatus::WaitingForBackend,
        "status transitions to WaitingForBackend after all tools complete"
    );

    // Effect assertions: ToolCallCompleted + ExecuteBackend
    assert_eq!(
        effects_3.len(),
        2,
        "ToolCompleted should produce exactly 2 effects"
    );

    let has_tool_completed = effects_3.iter().any(|e| {
        matches!(
            e,
            AgentEffect::Emit {
                event: AgentEvent::ToolCallCompleted {
                    call_id,
                    result,
                },
            } if *call_id == tool_call_id && !result.has_error
        )
    });
    assert!(
        has_tool_completed,
        "effect[0]: ToolCallCompleted with has_error=false"
    );

    let has_next_backend = effects_3
        .iter()
        .any(|e| matches!(e, AgentEffect::ExecuteBackend { .. }));
    assert!(
        has_next_backend,
        "effect[1]: ExecuteBackend to continue run"
    );

    // ------------------------------------------------------------------
    // Step 4: BackendEvent(UsageUpdate) with partially-known usage
    // ------------------------------------------------------------------
    let _effects_usage = agent.apply(AgentCommand::BackendEvent {
        run_id,
        event: ExecutionEvent::UsageUpdate {
            request_id: RequestId::new(),
            usage: ModelUsage {
                input_tokens: UsageValue::new(Some(5)),
                output_tokens: UsageValue::new(Some(10)),
                cache_read_tokens: UsageValue::new(None),
                cache_write_tokens: UsageValue::new(None),
                reasoning_tokens: UsageValue::new(None),
                total_tokens: UsageValue::new(Some(15)),
            },
        },
    });

    // UsageUpdate produces no effects (returns vec![])
    // But it mutates the usage ledger
    assert_eq!(
        agent.usage.records.len(),
        1,
        "one usage record after UsageUpdate"
    );

    // ------------------------------------------------------------------
    // Step 5: BackendEvent(Completed)
    // ------------------------------------------------------------------
    let final_usage = ModelUsage {
        input_tokens: UsageValue::new(Some(10)),
        output_tokens: UsageValue::new(Some(20)),
        cache_read_tokens: UsageValue::new(None),
        cache_write_tokens: UsageValue::new(None),
        reasoning_tokens: UsageValue::new(Some(5)),
        total_tokens: UsageValue::new(Some(35)),
    };

    let effects_4 = agent.apply(AgentCommand::BackendEvent {
        run_id,
        event: ExecutionEvent::Completed {
            request_id: RequestId::new(),
            result: ExecutionResult {
                request_id: RequestId::new(),
                usage: final_usage.clone(),
                cost: Cost {
                    amount_usd: None,
                    source: None,
                },
                finish_reason: "end_turn".into(),
            },
        },
    });

    // Final state assertions
    assert_eq!(
        agent.state.status,
        AgentStatus::Idle,
        "after Completed: status returns to Idle"
    );
    assert!(
        agent.state.active_run.is_none(),
        "active_run cleared after completion"
    );
    assert!(
        agent.state.pending_tools.is_empty(),
        "no pending tools at end"
    );

    // Usage ledger should have 2 records (UsageUpdate + Completed)
    assert_eq!(
        agent.usage.records.len(),
        2,
        "two usage records: UsageUpdate + Completed"
    );

    // Verify the final usage record has the correct values
    let final_record = &agent.usage.records[1];
    assert_eq!(
        final_record.model_usage.input_tokens.value(),
        Some(10),
        "final input_tokens"
    );
    assert_eq!(
        final_record.model_usage.output_tokens.value(),
        Some(20),
        "final output_tokens"
    );
    assert!(
        final_record.model_usage.cache_read_tokens.is_unknown(),
        "cache_read_tokens stays unknown"
    );
    assert!(
        final_record.model_usage.cache_write_tokens.is_unknown(),
        "cache_write_tokens stays unknown"
    );
    assert_eq!(
        final_record.model_usage.reasoning_tokens.value(),
        Some(5),
        "final reasoning_tokens"
    );
    assert_eq!(
        final_record.model_usage.total_tokens.value(),
        Some(35),
        "final total_tokens"
    );

    // Effect assertions after Completed
    assert_eq!(effects_4.len(), 3, "Completed should produce exactly 3 effects");

    let has_final_state_changed = effects_4.iter().any(|e| {
        matches!(
            e,
            AgentEffect::Emit {
                event: AgentEvent::StateChanged {
                    from: AgentStatus::WaitingForBackend,
                    to: AgentStatus::Idle,
                },
            }
        )
    });
    assert!(
        has_final_state_changed,
        "effect[0]: StateChanged(WaitingForBackend -> Idle)"
    );

    let has_completed_event = effects_4.iter().any(|e| {
        matches!(
            e,
            AgentEffect::Emit {
                event: AgentEvent::Completed {
                    outcome: AgentOutcome::Success,
                },
            }
        )
    });
    assert!(has_completed_event, "effect[1]: Completed(Success)");

    let has_finish_run = effects_4
        .iter()
        .any(|e| matches!(e, AgentEffect::FinishRun { .. }));
    assert!(has_finish_run, "effect[2]: FinishRun");

    // ------------------------------------------------------------------
    // Verify the "unknown is not zero" invariant through the full run
    // ------------------------------------------------------------------
    // The UsageUpdate had output_tokens=Some(10), the Completed had
    // output_tokens=Some(20). Both are known, so aggregating should
    // give Some(30).
    let agg_output = agent
        .usage
        .records
        .iter()
        .fold(UsageValue::new(None), |acc, r| {
            acc.checked_add(r.model_usage.output_tokens)
        });
    assert_eq!(
        agg_output.value(),
        Some(30),
        "aggregated output_tokens should be sum of known values"
    );

    // cache_write_tokens was never reported — must stay unknown
    let agg_cache_write = agent
        .usage
        .records
        .iter()
        .fold(UsageValue::new(None), |acc, r| {
            acc.checked_add(r.model_usage.cache_write_tokens)
        });
    assert!(
        agg_cache_write.is_unknown(),
        "cache_write_tokens must stay unknown through entire run"
    );
}

//! Backend descriptor, reference, binding, and execution types for the harness protocol.
//!
//! This module defines how backends are described (capabilities, identity),
//! how they are referenced for persistence, how execution requests are structured,
//! and how execution events and results flow back to the agent.

use serde::{Deserialize, Serialize};

use crate::ids::{
    BackendId, ConfigurationId, IntegrationId, ModelId, RequestId, RunId,
};

use crate::messages::AgentMessage;
use crate::tools::{ToolCall, ToolDescriptor};
use crate::usage::{Cost, ModelUsage};

// ---------------------------------------------------------------------------
// Backend identity & capabilities
// ---------------------------------------------------------------------------

/// Full descriptor of a backend, including its identity and capabilities.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct BackendDescriptor {
    /// Unique identifier for this backend instance.
    pub id: BackendId,
    /// Human-readable name (e.g. "Anthropic", "Claude Code").
    pub name: String,
    /// A short description of the backend's purpose.
    pub description: String,
    /// The set of capabilities this backend supports.
    pub capabilities: BackendCapabilities,
}

/// Declares which optional features a backend supports.
///
/// This is the primary mechanism for capability-based dispatch.
/// Consumers must **never** branch on backend identity;
/// they should inspect these boolean flags instead.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct BackendCapabilities {
    /// Whether the backend can stream partial response deltas.
    pub streaming: bool,
    /// Whether the backend exposes a separate reasoning/thinking stream.
    pub reasoning_stream: bool,
    /// Whether the backend supports tool/function calls.
    pub tool_calls: bool,
    /// Whether the backend can issue multiple tool calls in one response.
    pub parallel_tool_calls: bool,
    /// Whether the *host* (harness runtime) manages tool execution.
    pub host_managed_tools: bool,
    /// Whether the *backend* itself manages tool execution.
    pub backend_managed_tools: bool,
    /// Whether the backend has a permission/approval system.
    pub permissions: bool,
    /// Whether the backend supports image inputs.
    pub images: bool,
    /// Whether the backend can resume interrupted sessions.
    pub resumable_sessions: bool,
    /// Whether the backend has native subagent support.
    pub native_subagents: bool,
    /// Whether the model can be switched mid-session.
    pub model_switching: bool,
    /// Whether the backend reports exact token usage.
    pub exact_usage: bool,
    /// Whether the backend reports exact cost information.
    pub exact_cost: bool,
}

impl Default for BackendCapabilities {
    fn default() -> Self {
        Self {
            streaming: false,
            reasoning_stream: false,
            tool_calls: false,
            parallel_tool_calls: false,
            host_managed_tools: false,
            backend_managed_tools: false,
            permissions: false,
            images: false,
            resumable_sessions: false,
            native_subagents: false,
            model_switching: false,
            exact_usage: false,
            exact_cost: false,
        }
    }
}

// ---------------------------------------------------------------------------
// Backend reference & binding
// ---------------------------------------------------------------------------

/// A persistable reference to a backend configuration.
///
/// This is what gets stored in session/agent state so the runtime can
/// reconstruct a concrete [`ExecutionBackend`] at restore time.
///
/// Credentials are **never** stored in this reference; they belong in
/// the integration configuration store.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct BackendReference {
    /// Which integration family (e.g. `"anthropic"`, `"codex"`).
    pub integration: IntegrationId,
    /// Which saved configuration (e.g. `"work-account"`, `"personal"`).
    pub configuration: ConfigurationId,
    /// Optional model override within that integration.
    pub model: Option<ModelId>,
}

/// A full backend binding combining a persistable reference and a live descriptor.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct BackendBinding {
    /// The persistable reference to the backend configuration.
    pub reference: BackendReference,
    /// The live descriptor, used by the agent to inspect capabilities.
    pub descriptor: BackendDescriptor,
}

// ---------------------------------------------------------------------------
// Execution request & context
// ---------------------------------------------------------------------------

/// A complete request to be sent to an execution backend.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ExecutionRequest {
    /// Unique identifier for this request.
    pub request_id: RequestId,
    /// The run this request belongs to.
    pub run_id: RunId,
    /// The system prompt / instruction for the agent.
    pub system_prompt: String,
    /// The conversation history so far.
    pub messages: Vec<AgentMessage>,
    /// The tools the agent is allowed to use.
    pub tools: Vec<ToolDescriptor>,
    /// Whether to request extended thinking / reasoning from the backend.
    pub extended_thinking: bool,
}

/// Parameters that control how a backend executes a request.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ExecutionContext {
    /// Maximum number of tokens to generate.
    pub max_tokens: Option<u64>,
    /// Sampling temperature (0.0–1.0 or higher).
    pub temperature: Option<f64>,
    /// Sequences that will stop generation when encountered.
    pub stop_sequences: Vec<String>,
}

// ---------------------------------------------------------------------------
// Execution result
// ---------------------------------------------------------------------------

/// The final result of a backend execution request.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct ExecutionResult {
    /// The request this result belongs to.
    pub request_id: RequestId,
    /// Token usage for this execution.
    pub usage: ModelUsage,
    /// Financial cost of this execution, if known.
    pub cost: Cost,
    /// Reason why execution finished (e.g. "end_turn", "max_tokens", "stop").
    pub finish_reason: String,
}

// ---------------------------------------------------------------------------
// Execution error
// ---------------------------------------------------------------------------

/// Errors that can occur during backend execution.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub enum ExecutionError {
    /// A general backend error occurred.
    BackendError {
        /// Human-readable error message.
        message: String,
        /// Machine-readable error code.
        code: String,
    },
    /// The request was rate-limited by the backend.
    RateLimited {
        /// How long to wait before retrying, if known.
        retry_after: Option<u64>,
    },
    /// The request was invalid and cannot be retried as-is.
    InvalidRequest {
        /// Explanation of what was invalid.
        message: String,
    },
    /// The execution was cancelled.
    Cancelled,
    /// The execution timed out.
    Timeout,
}

// ---------------------------------------------------------------------------
// Execution event
// ---------------------------------------------------------------------------

/// An event emitted during backend execution.
///
/// These events are consumed by the agent's transition function and
/// represent the normalized interface between backends and the agent.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub enum ExecutionEvent {
    /// A delta of assistant text output.
    TextDelta {
        /// The request this event belongs to.
        request_id: RequestId,
        /// The incremental text chunk.
        delta: String,
    },
    /// A delta of reasoning/thinking content (backend-dependent).
    ReasoningDelta {
        /// The request this event belongs to.
        request_id: RequestId,
        /// The incremental reasoning chunk.
        delta: String,
    },
    /// A tool call was requested by the model.
    ToolCallRequested {
        /// The request this event belongs to.
        request_id: RequestId,
        /// The tool call details.
        call: ToolCall,
    },
    /// An update on token usage so far.
    UsageUpdate {
        /// The request this event belongs to.
        request_id: RequestId,
        /// Accumulated usage so far.
        usage: ModelUsage,
    },
    /// Execution completed successfully.
    Completed {
        /// The request this event belongs to.
        request_id: RequestId,
        /// The final result.
        result: ExecutionResult,
    },
    /// Execution failed with an error.
    Error {
        /// The request this event belongs to.
        request_id: RequestId,
        /// The error that occurred.
        error: ExecutionError,
    },
}

// ---------------------------------------------------------------------------
// Tests
// ---------------------------------------------------------------------------

#[cfg(test)]
mod tests {
    use super::*;
    use crate::ids::BackendId;

    // -----------------------------------------------------------------------
    // Capability-based branching
    // -----------------------------------------------------------------------

    /// Demonstrates that capability-based dispatch compiles and works correctly.
    #[test]
    fn capability_branching_works() {
        let caps = BackendCapabilities {
            streaming: true,
            tool_calls: true,
            ..Default::default()
        };

        // Simulate capability-based dispatch
        let use_streaming = caps.streaming;
        let use_tools = caps.tool_calls;
        let use_reasoning = caps.reasoning_stream;
        let use_images = caps.images;

        assert!(use_streaming, "streaming should be enabled");
        assert!(use_tools, "tool_calls should be enabled");
        assert!(!use_reasoning, "reasoning_stream should be disabled by default");
        assert!(!use_images, "images should be disabled by default");

        // All-zeros default
        let default_caps = BackendCapabilities::default();
        assert!(!default_caps.streaming);
        assert!(!default_caps.exact_cost);
        assert!(!default_caps.resumable_sessions);
    }

    /// Verifies that a backend descriptor round-trips through JSON with
    /// a mix of enabled and disabled capabilities.
    #[test]
    fn backend_descriptor_roundtrip() {
        let desc = BackendDescriptor {
            id: BackendId::new(),
            name: "test-backend".into(),
            description: "A test backend".into(),
            capabilities: BackendCapabilities {
                streaming: true,
                tool_calls: true,
                parallel_tool_calls: true,
                host_managed_tools: true,
                ..Default::default()
            },
        };

        let json = serde_json::to_string(&desc).expect("serialize descriptor");
        let deserialized: BackendDescriptor =
            serde_json::from_str(&json).expect("deserialize descriptor");

        assert_eq!(desc.id, deserialized.id);
        assert_eq!(desc.name, deserialized.name);
        assert_eq!(desc.capabilities.streaming, deserialized.capabilities.streaming);
        assert_eq!(desc.capabilities.tool_calls, deserialized.capabilities.tool_calls);
        assert_eq!(
            desc.capabilities.parallel_tool_calls,
            deserialized.capabilities.parallel_tool_calls
        );
        assert!(!deserialized.capabilities.reasoning_stream);
        assert!(!deserialized.capabilities.exact_cost);
    }

    // -----------------------------------------------------------------------
    // BackendReference / BackendBinding
    // -----------------------------------------------------------------------

    #[test]
    fn backend_reference_roundtrip() {
        let reference = BackendReference {
            integration: IntegrationId::new(),
            configuration: ConfigurationId::new(),
            model: None,
        };

        let json = serde_json::to_string(&reference).expect("serialize reference");
        let deserialized: BackendReference =
            serde_json::from_str(&json).expect("deserialize reference");

        assert_eq!(reference.integration, deserialized.integration);
        assert_eq!(reference.configuration, deserialized.configuration);
        assert!(deserialized.model.is_none());
    }

    #[test]
    fn backend_binding_roundtrip() {
        let binding = BackendBinding {
            reference: BackendReference {
                integration: IntegrationId::new(),
                configuration: ConfigurationId::new(),
                model: Some(ModelId::new()),
            },
            descriptor: BackendDescriptor {
                id: BackendId::new(),
                name: "production".into(),
                description: "Production backend".into(),
                capabilities: BackendCapabilities {
                    streaming: true,
                    ..Default::default()
                },
            },
        };

        let json = serde_json::to_string(&binding).expect("serialize binding");
        let deserialized: BackendBinding =
            serde_json::from_str(&json).expect("deserialize binding");

        assert_eq!(binding.reference.integration, deserialized.reference.integration);
        assert_eq!(
            binding.descriptor.name,
            deserialized.descriptor.name
        );
        assert!(deserialized.reference.model.is_some());
    }

    // -----------------------------------------------------------------------
    // ExecutionRequest / ExecutionContext
    // -----------------------------------------------------------------------

    #[test]
    fn execution_request_roundtrip() {
        let request = ExecutionRequest {
            request_id: RequestId::new(),
            run_id: RunId::new(),
            system_prompt: "You are a helpful assistant.".into(),
            messages: vec![],
            tools: vec![],
            extended_thinking: false,
        };

        let json = serde_json::to_string(&request).expect("serialize request");
        let deserialized: ExecutionRequest =
            serde_json::from_str(&json).expect("deserialize request");

        assert_eq!(request.request_id, deserialized.request_id);
        assert_eq!(request.run_id, deserialized.run_id);
        assert_eq!(request.system_prompt, deserialized.system_prompt);
