        AgentMessage, ContentBlock, MessageRole, ToolCall, ToolResultSummary,
    };

    use super::*;

    /// Helper: creates a user message with text content.
    fn user_message(text: &str) -> AgentMessage {
        AgentMessage {
            id: MessageId::new(),
            role: MessageRole::User,
            content: vec![ContentBlock::Text {
                text: text.to_string(),
            }],
            created_at: Timestamp::now(),
        }
    }

    /// Helper: creates an assistant message with a single tool-use block.
    fn assistant_with_tool_call(call_id: ToolCallId) -> AgentMessage {
        AgentMessage {
            id: MessageId::new(),
            role: MessageRole::Assistant,
            content: vec![ContentBlock::ToolUse {
                call: ToolCall {
                    id: call_id,
                    name: "test-tool".to_string(),
                    arguments: serde_json::json!({}),
                },
            }],
            created_at: Timestamp::now(),
        }
    }

    /// Helper: creates a tool message with a single tool-result block.
    fn tool_with_result(call_id: ToolCallId) -> AgentMessage {
        AgentMessage {
            id: MessageId::new(),
            role: MessageRole::Tool,
            content: vec![ContentBlock::ToolResult {
                call_id,
                result: ToolResultSummary {
                    is_error: false,
                    output: serde_json::json!({"result": "ok"}),
                },
            }],
            created_at: Timestamp::now(),
        }
    }

    /// Helper: creates a system message with text content.
    fn system_message(text: &str) -> AgentMessage {
        AgentMessage {
            id: MessageId::new(),
            role: MessageRole::System,
            content: vec![ContentBlock::Text {
                text: text.to_string(),
            }],
            created_at: Timestamp::now(),
        }
    }

    // -----------------------------------------------------------------------
    // Valid transcripts
    // -----------------------------------------------------------------------

    #[test]
    fn valid_tool_call_then_result_then_user() {
        let call_id = ToolCallId::new();
        let messages = vec![
            assistant_with_tool_call(call_id),
            tool_with_result(call_id),
            user_message("ok"),
        ];

        assert!(validate_transcript(&messages).is_ok());
    }

    #[test]
    fn valid_with_system_message() {
        let call_id = ToolCallId::new();
        let messages = vec![
            system_message("You are a helpful assistant."),
            assistant_with_tool_call(call_id),
            tool_with_result(call_id),
            user_message("thanks"),
        ];

        assert!(validate_transcript(&messages).is_ok());
    }

    #[test]
    fn valid_multiple_tool_calls_in_order() {
        let id_a = ToolCallId::new();
        let id_b = ToolCallId::new();
        let messages = vec![
            assistant_with_tool_call(id_a),
            tool_with_result(id_a),
            assistant_with_tool_call(id_b),
            tool_with_result(id_b),
            user_message("done"),
