        assert!(validate_transcript(&messages).is_ok());
    }

    #[test]
    fn valid_user_only_transcript() {
        let messages = vec![user_message("hello")];
        assert!(validate_transcript(&messages).is_ok());
    }

    // -----------------------------------------------------------------------
    // Dangling tool calls (conversational message interrupts)
    // -----------------------------------------------------------------------

    #[test]
    fn dangling_unresolved_tool_call_before_user() {
        let call_id = ToolCallId::new();
        let messages = vec![
            assistant_with_tool_call(call_id),
            // User message before tool result — DanglingToolCall
