        ];

        let result = validate_transcript(&messages);
        assert!(result.is_err());
        match result {
            Err(TranscriptError::DanglingToolCall(id)) => assert_eq!(id, call_id),
            other => panic!("expected DanglingToolCall, got {other:?}"),
        }
    }

    // -----------------------------------------------------------------------
    // Unresolved tool calls (end of transcript)
    // -----------------------------------------------------------------------

    #[test]
    fn unresolved_tool_call_at_end() {
        let call_id = ToolCallId::new();
        let messages = vec![assistant_with_tool_call(call_id)];

        let result = validate_transcript(&messages);
        assert!(result.is_err());
        match result {
            Err(TranscriptError::UnresolvedToolCall(id)) => assert_eq!(id, call_id),
            other => panic!("expected UnresolvedToolCall, got {other:?}"),
        }
    }

    #[test]
    fn multiple_unresolved_tool_calls_at_end() {
        let id_a = ToolCallId::new();
        let id_b = ToolCallId::new();
        let messages = vec![
            assistant_with_tool_call(id_a),
            assistant_with_tool_call(id_b),
        ];

        let result = validate_transcript(&messages);
        assert!(result.is_err());
        // Should report id_a (the first pending call)
