#[cfg(test)]
mod tests {
    use std::collections::HashMap;

    use harness_protocol::backend::{
        BackendBinding, BackendCapabilities, BackendDescriptor, BackendReference,
        ExecutionEvent, ExecutionResult,
    };
    use harness_protocol::commands::{
        AgentCommand, AgentStatus, PermissionDecision, UserInput,
    };
    use harness_protocol::effects::AgentEffect;
    use harness_protocol::events::{AgentEvent, AgentOutcome};
    use harness_protocol::ids::{
        AgentId, BackendId, ConfigurationId, IntegrationId, RunId, SessionId, ToolCallId, ToolId,
    };
    use harness_protocol::tools::{
        AgentToolset, PermissionMode, ToolCall, ToolCapability, ToolDescriptor, ToolPolicy,
        ToolResult,
    };
    use harness_protocol::usage::{AgentBudget, Cost, ModelUsage, UsageValue};

    use crate::agent::Agent;
    use crate::capabilities::{AgentCapabilities, WorkspaceCapabilities};

    // -----------------------------------------------------------------------
    // Test helpers
    // -----------------------------------------------------------------------

    /// Creates a minimal `AgentCapabilities` for testing.
    fn test_capabilities() -> AgentCapabilities {
        let tool_id = ToolId::new();
        let mut tools = HashMap::new();
        tools.insert(
            tool_id,
            ToolCapability {
                descriptor: ToolDescriptor {
                    id: tool_id,
                    name: "test-tool".into(),
                    description: "A test tool".into(),
                    input_schema: serde_json::json!({}),
                },
                policy: ToolPolicy {
                    permission: PermissionMode::Allow,
                    enabled: true,
                },
                delegatable: true,
            },
        );

        AgentCapabilities {
            tools: AgentToolset { tools },
            can_spawn_agents: true,
            max_child_depth: Some(5),
            workspace: WorkspaceCapabilities {
                can_read: true,
                can_write: false,
                can_search: false,
            },
            backend: BackendCapabilities {
                tool_calls: true,
                ..Default::default()
            },
        }
    }

    /// Creates a minimal `BackendBinding` for testing.
    fn test_backend() -> BackendBinding {
        BackendBinding {
            reference: BackendReference {
                integration: IntegrationId::new(),
                configuration: ConfigurationId::new(),
                model: None,
            },
            descriptor: BackendDescriptor {
                id: BackendId::new(),
                name: "test-backend".into(),
                description: "Test backend".into(),
                capabilities: BackendCapabilities {
                    tool_calls: true,
                    ..Default::default()
                },
            },
        }
    }

    /// Creates a root agent for testing.
    fn create_test_agent() -> Agent {
        Agent::new(
            AgentId::new(),
            SessionId::new(),
            None,
            "You are a helpful assistant.".to_string(),
            test_backend(),
            test_capabilities(),
            AgentBudget {
                max_total_tokens: Some(100_000),
                ..Default::default()
            },
        )
    }

    // -----------------------------------------------------------------------
    // start_run
    // -----------------------------------------------------------------------

    #[test]
    fn start_run_from_idle_emits_execute_backend_and_run_started() {
        let mut agent = create_test_agent();
        assert_eq!(agent.state.status, AgentStatus::Idle);

        let effects = agent.apply(AgentCommand::StartRun {
            input: UserInput {
                text: "Hello".into(),
                attachments: vec![],
            },
        });

        // Status must transition to PreparingContext
        assert_eq!(agent.state.status, AgentStatus::PreparingContext);
        assert!(agent.state.active_run.is_some());

        // Must contain ExecuteBackend + Emit(RunStarted) + StateChanged
        let has_execute = effects
            .iter()
            .any(|e| matches!(e, AgentEffect::ExecuteBackend { .. }));
        assert!(has_execute, "expected ExecuteBackend effect");

        let has_run_started = effects.iter().any(|e| {
            matches!(e, AgentEffect::Emit { event: AgentEvent::RunStarted { .. } })
        });
        assert!(has_run_started, "expected RunStarted event");

        let has_state_changed = effects.iter().any(|e| {
            matches!(e, AgentEffect::Emit { event: AgentEvent::StateChanged { from: AgentStatus::Idle, to: AgentStatus::PreparingContext } })
        });
        assert!(has_state_changed, "expected StateChanged(Idle->PreparingContext)");
    }

    // -----------------------------------------------------------------------
    // tool_call
    // -----------------------------------------------------------------------

    #[test]
    fn tool_call_requested_adds_to_pending_tools() {
        let mut agent = create_test_agent();

        // First start a run
        agent.state.status = AgentStatus::WaitingForBackend;
        let run_id = RunId::new();
        agent.state.active_run = Some(run_id);

        let tool_call = ToolCall {
            id: ToolCallId::new(),
            name: "test-tool".into(),
            arguments: serde_json::json!({"key": "value"}),
        };
        let call_id = tool_call.id;

        let effects = agent.apply(AgentCommand::BackendEvent {
            run_id,
            event: ExecutionEvent::ToolCallRequested {
                request_id: harness_protocol::ids::RequestId::new(),
                call: tool_call,
            },
        });

        // Pending tools should contain the call
        assert!(agent.state.pending_tools.contains_key(&call_id));

        // Must emit ToolCallRequested event
        let has_tool_event = effects.iter().any(|e| {
            matches!(e, AgentEffect::Emit { event: AgentEvent::ToolCallRequested { .. } })
        });
        assert!(has_tool_event, "expected ToolCallRequested event");
    }

    // -----------------------------------------------------------------------
    // cancel
    // -----------------------------------------------------------------------

    #[test]
    fn cancel_sets_status_to_cancelled() {
        let mut agent = create_test_agent();
        agent.state.status = AgentStatus::Streaming;
        agent.state.active_run = Some(RunId::new());

        let effects = agent.apply(AgentCommand::Cancel);

        assert_eq!(agent.state.status, AgentStatus::Cancelled);
        assert!(agent.state.active_run.is_none());

        let has_completed = effects.iter().any(|e| {
            matches!(e, AgentEffect::Emit { event: AgentEvent::Completed { outcome: AgentOutcome::Cancelled } })
        });
        assert!(has_completed, "expected Completed(Cancelled) event");
    }

    // -----------------------------------------------------------------------
    // permission — approved
    // -----------------------------------------------------------------------

    #[test]
    fn permission_approved_transitions_to_executing() {
        let mut agent = create_test_agent();
        agent.state.status = AgentStatus::WaitingForPermission;

        let effects = agent.apply(AgentCommand::PermissionResolved {
            id: harness_protocol::ids::PermissionId::new(),
            decision: PermissionDecision::Approved,
        });

        assert_eq!(agent.state.status, AgentStatus::Executing);

        let has_state_change = effects.iter().any(|e| {
            matches!(e, AgentEffect::Emit { event: AgentEvent::StateChanged { from: AgentStatus::WaitingForPermission, to: AgentStatus::Executing } })
        });
        assert!(has_state_change, "expected StateChanged(WaitingForPermission->Executing)");
    }

    // -----------------------------------------------------------------------
    // permission — denied
    // -----------------------------------------------------------------------

    #[test]
    fn permission_denied_continues_with_backend_request() {
        let mut agent = create_test_agent();
        agent.state.status = AgentStatus::WaitingForPermission;
        let run_id = RunId::new();
        agent.state.active_run = Some(run_id);

        let effects = agent.apply(AgentCommand::PermissionResolved {
            id: harness_protocol::ids::PermissionId::new(),
            decision: PermissionDecision::Denied,
        });

        assert_eq!(agent.state.status, AgentStatus::PreparingContext);

        let has_execute = effects
            .iter()
            .any(|e| matches!(e, AgentEffect::ExecuteBackend { .. }));
        assert!(has_execute, "expected ExecuteBackend after denial");
    }

    // -----------------------------------------------------------------------
    // pause / resume
    // -----------------------------------------------------------------------

    #[test]
    fn pause_and_resume() {
        let mut agent = create_test_agent();
        agent.state.status = AgentStatus::Streaming;
        let run_id = RunId::new();
        agent.state.active_run = Some(run_id);

        // Pause
        let pause_effects = agent.apply(AgentCommand::Pause);
        assert_eq!(agent.state.status, AgentStatus::Paused);

        let has_state_change = pause_effects.iter().any(|e| {
            matches!(e, AgentEffect::Emit { event: AgentEvent::StateChanged { from: AgentStatus::Streaming, to: AgentStatus::Paused } })
        });
        assert!(has_state_change, "expected StateChanged(Streaming->Paused)");

        // Resume
        let resume_effects = agent.apply(AgentCommand::Resume);
        assert_eq!(agent.state.status, AgentStatus::WaitingForBackend);

        let has_execute = resume_effects
            .iter()
            .any(|e| matches!(e, AgentEffect::ExecuteBackend { .. }));
        assert!(has_execute, "expected ExecuteBackend after resume");
    }

    // -----------------------------------------------------------------------
    // Scripted sequence: StartRun → ToolCallRequested → ToolCompleted → Completed
    // -----------------------------------------------------------------------

    #[test]
    fn scripted_sequence_happy_path() {
        let mut agent = create_test_agent();
        let tool_call_id = ToolCallId::new();

        // --- Step 1: StartRun ---
        let effects_1 = agent.apply(AgentCommand::StartRun {
            input: UserInput {
                text: "Do something".into(),
                attachments: vec![],
            },
        });

        assert_eq!(agent.state.status, AgentStatus::PreparingContext);
        let run_id = agent.state.active_run.expect("run_id must be set");

        // Check ExecuteBackend effect
        let exec_backend = effects_1.iter().find_map(|e| {
            if let AgentEffect::ExecuteBackend { request } = e {
                Some(request.clone())
            } else {
                None
            }
        });
        assert!(exec_backend.is_some(), "expected ExecuteBackend");

        // Check RunStarted event
        let has_run_started = effects_1.iter().any(|e| {
            matches!(e, AgentEffect::Emit { event: AgentEvent::RunStarted { .. } })
        });
        assert!(has_run_started, "expected RunStarted");

        // --- Step 2: ToolCallRequested ---
        let effects_2 = agent.apply(AgentCommand::BackendEvent {
            run_id,
            event: ExecutionEvent::ToolCallRequested {
                request_id: harness_protocol::ids::RequestId::new(),
                call: ToolCall {
                    id: tool_call_id,
                    name: "test-tool".into(),
                    arguments: serde_json::json!({"input": "test"}),
                },
            },
        });

        assert!(
            agent.state.pending_tools.contains_key(&tool_call_id),
            "tool call should be pending"
        );

        let has_tool_event = effects_2.iter().any(|e| {
            matches!(e, AgentEffect::Emit { event: AgentEvent::ToolCallRequested { .. } })
        });
        assert!(has_tool_event, "expected ToolCallRequested event");

        // --- Step 3: ToolCompleted ---
        let effects_3 = agent.apply(AgentCommand::ToolCompleted {
            call_id: tool_call_id,
            result: ToolResult {
                call_id: tool_call_id,
                output: serde_json::json!({"result": "ok"}),
                is_error: false,
            },
        });

        assert!(
            !agent.state.pending_tools.contains_key(&tool_call_id),
            "tool call should be removed from pending"
        );

        // After tool completion, should see ToolCallCompleted + ExecuteBackend
        // (since pending is now empty and active_run is set)
        let has_tool_completed = effects_3.iter().any(|e| {
            matches!(e, AgentEffect::Emit { event: AgentEvent::ToolCallCompleted { .. } })
        });
        assert!(has_tool_completed, "expected ToolCallCompleted event");

        let has_next_backend = effects_3
            .iter()
            .any(|e| matches!(e, AgentEffect::ExecuteBackend { .. }));
        assert!(has_next_backend, "expected ExecuteBackend after tool completion");

        // --- Step 4: BackendEvent(Completed) ---
        let final_usage = ModelUsage {
            input_tokens: UsageValue::new(Some(10)),
            output_tokens: UsageValue::new(Some(20)),
            cache_read_tokens: UsageValue::new(None),
            cache_write_tokens: UsageValue::new(None),
            reasoning_tokens: UsageValue::new(Some(5)),
            total_tokens: UsageValue::new(Some(35)),
        };

        let effects_4 = agent.apply(AgentCommand::BackendEvent {
            run_id,
            event: ExecutionEvent::Completed {
                request_id: harness_protocol::ids::RequestId::new(),
                result: ExecutionResult {
                    request_id: harness_protocol::ids::RequestId::new(),
                    usage: final_usage.clone(),
                    cost: Cost {
                        amount_usd: None,
                        source: None,
                    },
                    finish_reason: "end_turn".into(),
                },
            },
        });

        // Final state: Idle, no active run
        assert_eq!(agent.state.status, AgentStatus::Idle);
        assert!(agent.state.active_run.is_none());

        // Usage should be recorded
        assert!(!agent.usage.records.is_empty(), "usage should be recorded");

        // Effects should include Completed + FinishRun
        let has_completed = effects_4.iter().any(|e| {
            matches!(e, AgentEffect::Emit { event: AgentEvent::Completed { outcome: AgentOutcome::Success } })
        });
        assert!(has_completed, "expected Completed(Success) event");

        let has_finish = effects_4
            .iter()
            .any(|e| matches!(e, AgentEffect::FinishRun { .. }));
        assert!(has_finish, "expected FinishRun effect");
    }
}

//! Event types for the harness protocol.
//!
//! This module defines [`EventVisibility`], [`AgentEventEnvelope`], [`AgentEvent`],
//! and [`AgentOutcome`] — the observable events that an agent emits throughout
//! its lifecycle.  Events are wrapped in an envelope that carries routing and
//! ordering metadata.

use serde::{Deserialize, Serialize};

use crate::commands::{AgentError, AgentStatus};
use crate::effects::PermissionRequest;
use crate::ids::{
    AgentId, EventId, MessageId, RequestId, RunId, SessionId, Timestamp, ToolCallId,
};
use crate::tools::{ToolCall, ToolProgress, ToolResultSummary};
use crate::usage::AgentUsageSnapshot;

// ---------------------------------------------------------------------------
// EventVisibility
// ---------------------------------------------------------------------------

/// Controls which audience an event is visible to.
///
/// - [`User`](EventVisibility::User) — visible to end-users (shown in the UI).
/// - [`Developer`](EventVisibility::Developer) — visible to developers/extensions.
/// - [`Internal`](EventVisibility::Internal) — used for telemetry and logging only.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
pub enum EventVisibility {
    /// Visible to end-users (shown in the UI).
    User,
    /// Visible to developers/extensions.
    Developer,
    /// Used for telemetry and logging only.
    Internal,
}

// ---------------------------------------------------------------------------
// AgentOutcome
// ---------------------------------------------------------------------------

/// The final result of an agent run or child-agent execution.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash, Serialize, Deserialize)]
pub enum AgentOutcome {
    /// Agent completed its work successfully.
    Success,
    /// Agent was cancelled before completing.
    Cancelled,
    /// Agent encountered an unrecoverable error.
    Failed,
}

// ---------------------------------------------------------------------------
// AgentEventEnvelope
// ---------------------------------------------------------------------------

/// A fully qualified event emitted by an agent.
///
/// Every observable occurrence in the harness is wrapped in this envelope,
/// providing routing metadata (`session_id`, `agent_id`, `parent_agent_id`),
/// temporal context (`timestamp`, `run_id`), and ordering primitives.
///
/// ## Ordering
///
/// [`agent_sequence`](AgentEventEnvelope::agent_sequence) and
/// [`session_sequence`](AgentEventEnvelope::session_sequence) are **monotonic
/// counters** that clients should use to order events from a single agent or
/// session.  Do **not** rely on timestamps alone for ordering, especially
/// when multiple agents are executing concurrently — two events from different
/// agents may have identical timestamps but a well-defined causal order.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct AgentEventEnvelope {
    /// Unique identifier for this event (enables deduplication and replay).
    pub event_id: EventId,
    /// The session this event belongs to.
    pub session_id: SessionId,
    /// The agent that produced this event.
    pub agent_id: AgentId,
    /// The parent agent of the producing agent, if any (root agents have `None`).
    pub parent_agent_id: Option<AgentId>,
    /// The run this event is associated with, if any.
    pub run_id: Option<RunId>,
    /// Monotonic counter scoped to the producing agent.  Strictly increasing
    /// per agent — used to order events emitted by the same agent.
    pub agent_sequence: u64,
    /// Monotonic counter scoped to the entire session.  Present on events
    /// that flow through the session bus; `None` for agent-local events that
    /// have not yet been committed to the session stream.
    pub session_sequence: Option<u64>,
    /// Wall-clock timestamp of when the event was produced.
    pub timestamp: Timestamp,
    /// Controls which audience this event is visible to.
    pub visibility: EventVisibility,
    /// The event payload.
    pub event: AgentEvent,
}

// ---------------------------------------------------------------------------
// AgentEvent
// ---------------------------------------------------------------------------

/// The payload of an event emitted by an agent.
///
/// Each variant represents a distinct occurrence in the agent's lifecycle:
/// state transitions, backend interactions, tool calls, permission requests,
/// child-agent activity, and final outcomes.
#[derive(Debug, Clone, Serialize, Deserialize)]
pub enum AgentEvent {
    /// The agent's status changed (e.g. `Idle` → `PreparingContext`).
    StateChanged {
        /// The previous status.
        from: AgentStatus,
        /// The new status.
        to: AgentStatus,
    },

    /// A new run was started on this agent.
    RunStarted {
        /// The identifier of the newly created run.
        run_id: RunId,
    },

    /// A request was sent to the execution backend.
    BackendRequestStarted {
        /// The identifier of the backend request.
        request_id: RequestId,
    },

    /// The backend started producing a new assistant message.
    AssistantMessageStarted {
        /// The identifier of the assistant message.
        message_id: MessageId,
    },

    /// A text delta was received from the streaming backend for
    /// an in-progress assistant message.
    AssistantTextDelta {
        /// The message being streamed.
        message_id: MessageId,
        /// The incremental text chunk.
        delta: String,
    },

    /// A reasoning/thinking delta was received from the backend.
    ReasoningDelta {
        /// The message being streamed.
        message_id: MessageId,
        /// The incremental reasoning chunk.
        delta: String,
    },

    /// An assistant message finished streaming.
    AssistantMessageCompleted {
        /// The identifier of the completed message.
        message_id: MessageId,
    },

    /// The model requested a tool call.
    ToolCallRequested {
        /// The tool call details.
        call: ToolCall,
    },

    /// A tool call execution has started.
    ToolCallStarted {
        /// The identifier of the tool call being executed.
        call_id: ToolCallId,
    },

    /// Progress update for a long-running tool call.
    ToolCallProgress {
        /// The identifier of the tool call.
        call_id: ToolCallId,
        /// The current progress of the tool execution.
        progress: ToolProgress,
    },

    /// A tool call completed successfully.
    ToolCallCompleted {
        /// The identifier of the completed tool call.
        call_id: ToolCallId,
        /// A summary of the tool's result.
        result: ToolResultSummary,
    },

    /// The agent is waiting for a user permission decision.
    PermissionRequested {
        /// The permission request that needs resolution.
        request: PermissionRequest,
    },

    /// An update on the agent's token usage and cost.
    UsageUpdated {
        /// A snapshot of the agent's current usage.
        usage: AgentUsageSnapshot,
    },

    /// A child agent was spawned.
    ChildAgentSpawned {
        /// The identifier of the child agent.
        agent_id: AgentId,
    },

    /// A child agent completed its run.
    ChildAgentCompleted {
        /// The identifier of the child agent.
        agent_id: AgentId,
        /// The outcome of the child's run.
        outcome: AgentOutcome,
    },

    /// The agent encountered an unrecoverable error.
    Failed {
        /// Details about the error.
        error: AgentError,
    },

    /// The agent completed its run with the given outcome.
    Completed {
        /// The final outcome of the run.
        outcome: AgentOutcome,
    },
}

